globalThis.__NBA_UPDATE_ANNOUNCEMENTS__=[{"date":"2026-11-23","dateLabel":"2026年11月23日","introduction":["本次更新加入球队战术。你可以为球队定下一套常驻打法，也可以在赛前根据对手临场变阵，打完再看这套战术发挥得怎么样。轮换定位互换和抽签前的新秀预览也一并加入。"],"items":[{"title":"球队战术","description":"进入「管理 → 轮换战术 → 球队战术」，可选择 9 种进攻、7 种防守和 3 档节奏。保存前可以查看阵容契合度、战术熟练度、各位置的出手倾向和防守重点。比如，沉退护筐侧重限制对手内线，一盯四联则重点盯防对方第一进攻点。","category":"新增功能"},{"title":"赛前布置与赛后复盘","description":"在赛程里打开「赛前战术布置」，可预览调整效果，选择仅本场生效或设为常驻战术。侦察对手后可以查看对方打法，并一键采用推荐的克制方案。赛后到比赛详情查看战术带来的得失、对位原因和熟练度变化。","category":"新增功能"},{"title":"战术动画手册","description":"16 套攻防战术的动画免费查看。可以分步看球员怎么跑位、掩护和传球，也可以在相克总览里点开任意对位，查看哪一方占优以及原因。","category":"新增功能"},{"title":"轮换定位互换","description":"在轮换里照常修改球员的「当前定位」。如果名额或承诺冲突，游戏会提示原因，并列出可以互换的队友。两人都接受时可直接确认。有人拒绝时，只需为拒绝的球员观看说服视频，等双方同意后一起保存。","category":"新增功能"},{"title":"抽签前查看新秀","description":"在选秀准备页点击「查看新秀」，即可用与正式选秀相同的候选列表浏览本届球员，查看能力、潜力和球探信息，并按位置或国籍筛选。","category":"新增功能"},{"title":"交易列表补齐受限球员","description":"即使选择「全部球队」并留空姓名，列表也会显示受回购或合同限制的在队球员。操作按钮置灰，并标明限制原因。处于签约等待期的球员会显示可交易日期。","category":"修复与优化"},{"title":"界面更易阅读","description":"压缩选秀准备页的标题和概览卡片。浅色主题加深数据单项奖数字和部分状态标识的颜色。合同薪资页可折叠薪资占用明细，联盟排名的东西部和分区榜新增球队总评。","category":"修复与优化"},{"title":"读档与连续模拟","description":"从首页打开指定存档时，如果遇到其他页面占用，游戏会自动重试一次。连续模拟中，如果某一天的后台计算长时间无响应，游戏会尝试接续完成当天的结算。","category":"修复与优化"}]},{"date":"2026-11-21","dateLabel":"2026年11月21日","introduction":["本次更新带来 1·3·6 阵容适配赛。你可以拖动滑块分配出场时间，在保存前查看适配变化。新世代选秀也调整了 A+、A 档候选人数，并补齐拉希德·华莱士的历史新秀资料。本次还修复了部分市场报价白屏问题，并优化长生涯存档和拟真询价。"],"items":[{"title":"新增 1·3·6 阵容适配赛","description":"使用 24 维存档中的扩军球队参赛，赛季数不限。排好 5 名首发和 5 名替补，十人均须为真人球员。潜力配额为 1 个 S、3 个 A+、6 个 A，空出的名额可由任意更低档真人球员补齐。每人设置 8–40 分钟，全队合计 240 分钟。保存轮换后，到「管理 → 概览 → 球队阵容能力」点击「一键生图参赛」，即可生成并保存阵容海报。每日阵容适配分最高者将获得荣誉展示。","category":"新增功能"},{"title":"阵容轮换新增实时适配预览","description":"换人或调整出场时间时，可在保存前查看当前适配总分和变动项数。展开可看八项明细，有变化的项目会标出升降幅度。概览的「说明」移到「阵容适配明细」标题旁。","category":"新增功能"},{"title":"优化轮换调整与球员定位展示","description":"球员卡支持拖动滑块、加减和直接输入分钟。进攻顺序点「调整」展开，首发率、场均分钟和球队信任可在定位「详情」中查看。轮换已分满时，超出可分配分钟的滑动会保留原方案。","category":"修复与优化"},{"title":"调整 24 维常规选秀的高潜新秀人数","description":"尚未生成的常规届次将分别抽取 A+、A 档的人数。每届通常有 2–6 名 A+、5–10 名 A，最常见分别为 4 名和 7 名。S 档沿用原抽取方式，每届仍为 80 名候选。","category":"修复与优化"},{"title":"补齐拉希德·华莱士的历史新秀资料","description":"历史新秀池加入拉希德·华莱士的专属 24 维模板，配有真实头像和生涯介绍。他主打大前锋、兼任中锋，后续生成的新秀总评为 75，潜力 A+（89）。","category":"新增功能"},{"title":"修复市场报价白屏","description":"部分旧档的报价缺少球员或选秀权资料时，市场会标明资料不完整，正常报价仍可查看。三方交易遇到资料缺失时可返回列表，方案完整但缺少经理答复时可重新询价。自由市场对比会跳过资料异常的报价并提示。","category":"修复与优化"},{"title":"优化长生涯和存档","description":"收起球队历史的「赛季回顾」时会释放已加载的明细，再展开时按需加载。切换存档时更早释放旧数据，大体积存档有更多时间完成后台压缩。另存时只检查目标槽位，打开旧云存档列表也减少了一次重复请求。","category":"修复与优化"},{"title":"减少拟真询价的重复计算","description":"普通挂牌或定向询价首轮没有报价时，紧接着用同一方案扩大搜索，可复用部分球员估值和薪资校验结果。","category":"修复与优化"}]},{"date":"2026-11-20","dateLabel":"2026年11月20日","introduction":["本次更新统一了球队概览与交易详情的「阵容适配明细」并新增说明，补充新秀 3-2-1 乐透规则提示，调整自定义新秀为玩家主动选择，并更新游戏内反馈方式，同时优化启动加载与轮换保存体验。"],"items":[{"title":"统一阵容适配面板与新增明细说明","description":"「管理 → 球队概览」与交易详情共用「球队阵容能力」面板，概览将「替补深度」统一为「板凳深度」，并以对称双列加底部轮换结构展示八项明细及进度条；交易详情默认展开并逐项对比交易前后变化与差额。明细栏新增「说明」弹窗，清楚介绍综合总分高于 50 分在比赛中提供正效率加成（最高 +5.0）、低于 50 分产生拖累（最低 -5.0），以及组织、空间、球权分配等八项高分与低分各自代表的含义。","category":"新增功能"},{"title":"选秀准备与乐透页新增 3-2-1 规则说明","description":"2027 届起的选秀准备页、乐透抽签揭晓页及「管理 → 选秀权」弹窗新增「3-2-1 规则」说明入口，并在持签卡片、参抽概率列表与重抽提示中标明最差三队降档保底前 12、去年状元签本届禁状元、连续两年进前 5 本届禁前 5 等限制，说明限制跟随原签球队且交易不重置。首届 2026 真实顺位选秀与既有抽签规则不变。","category":"新增功能"},{"title":"自定义虚拟新秀改为玩家主动选择","description":"在开启球员轮回的新世代生涯中，开季确认与设置的「新秀规则」新增「优先采用自定义球员」开关，默认关闭；取消勾选 S 或 A+ 档真人模板时会弹出询问。开启后，未选用真人模板的 S、A+ 虚拟名额有同档自定义球员时即从中抽取，无合适人选时由普通虚拟新秀补齐。已生成名单与原有档位概率规则不变。","category":"修复与优化"},{"title":"游戏内反馈方式更新","description":"游戏内问题反馈入口已更新，可在设置中提交问题说明。","category":"修复与优化"},{"title":"改善启动加载容错与队徽兜底显示","description":"完善启动脚本及可选历史资源分片异常时的识别与重试恢复处理，减少部分情况下启动流程意外中断；减少背景图重复解码等待，并在队徽图片加载失败时及时显示文字缩写兜底。","category":"修复与优化"},{"title":"优化后台空闲时的轮换保存响应","description":"当后台模拟线程处于释放状态时，保存轮换和切换轮换模式改为直接就地执行，省去整份生涯数据的重复复制与传输；后台合并保存继续复用已确认的快照，让轮换保存和界面响应更顺畅。","category":"修复与优化"}],"closing":"已有存档可以继续游玩。自定义新秀主动选择只影响尚未生成的新秀届次；已生成名单、历史比赛数据与抽签算法保持原样。"},{"date":"2026-11-19","dateLabel":"2026年11月19日","introduction":["本次更新带来拟真三方交易，并优化阵容轮换、球探关注名单和历史新秀生成。"],"items":[{"title":"拟真模式支持三方交易","description":"挂牌或定向询价时，系统会尝试引入第三队，找到可行方案时会在报价中展示。已有双边报价时，也可以在谈判详情点击「邀请第三队」，调整球员和选秀权的去向。两位对方经理同意同一份方案后，即可确认成交。","category":"新增功能"},{"title":"轮回球员自动进入球探关注名单","description":"以前收藏过的球员重新参选时，会自动出现在球探中心的「关注名单」中。已经手动关注的球员只显示一次。","category":"新增功能"},{"title":"G 联赛下放球员单独显示","description":"阵容轮换在替补名单下方新增「G 联赛下放」分区，方便区分当前可用球员。需要召回时，可以直接点击「前往下放培养」。","category":"修复与优化"},{"title":"奥登、富尔茨的新秀总评随潜力浮动","description":"后续生成的24维历史新秀中，奥登潜力在83–95随机，新秀总评为75–80。富尔茨潜力在80–91随机，新秀总评为76–78。抽到的潜力越高，初始总评也相应提高。已生成的球员保留原数值。","category":"修复与优化"},{"title":"优化交易详情和报价列表","description":"「选择第三队」采用游戏内统一的筛选样式。报价列表展示交易前后的球队总评，详细轮换和薪资变化可在交易详情查看。","category":"修复与优化"},{"title":"电脑主动报价更有利于我方","description":"常规赛交易截止前，电脑新发来的报价须通过交易条件校验，且我方收到的球员和选秀权总估值高于送出。经典和拟真模式均适用。","category":"修复与优化"},{"title":"选交易筹码时直接看潜力","description":"我方和对方的筹码列表都会在球员总评旁显示潜力档位及已公开的潜力上限，方便选人时对比。","category":"新增功能"},{"title":"谈判参考的失败原因更具体","description":"如果试算对方裁员后仍无法达成交易，谈判参考会列出剩余限制。遇到薪资无法配平时，有差额记录的方案也会显示具体金额。","category":"修复与优化"},{"title":"历届选秀可以点姓名打开球员卡","description":"点击榜单上的球员姓名，即可打开标准球员卡查看个人资料和生涯数据。关闭后回到所选年份和之前的浏览位置。","category":"新增功能"},{"title":"球员卡新增「生涯场均」","description":"球员卡的「生涯数据」在「历季场均」和「生涯累计」之间新增「生涯场均」。得分、篮板、助攻等按生涯合计和实际出场数计算，常规赛和季后赛分开查看。","category":"新增功能"}]},{"date":"2026-11-18","dateLabel":"2026年11月18日","introduction":["我们发起了球员投稿活动，邀请大家提交想加入游戏的球员资料和球风设定。首批收录的球员将作为自定义虚拟新秀进入选秀池。感谢大家参与投稿！","本次更新也让轮回收藏、杯赛生涯荣誉和阵容轮换更好用。"],"items":[{"title":"新增35名S档自定义虚拟新秀","description":"首批名单包含常鹏飞。每人都有初始和巅峰两套24维能力模板及专属头像，首次参选时为18岁的中国球员。开启球员轮回的正式24维新世代生涯里，当届规则取消勾选S档真人模板后，每个已生成的S档虚拟名额有80%概率从符合条件的自定义球员中等概率抽取，其余名额或池内无人可选时由普通虚拟新秀补齐。新秀潜力档位继续按原概率生成。入选后沿用既有球员轮回规则。","category":"新增功能"},{"title":"轮回新秀显示收藏标记","description":"你关注过的球员退役后再次参选时，选秀大厅和球探中心会在姓名旁显示「★ 已收藏」。","category":"新增功能"},{"title":"杯赛MVP纳入球员生涯荣誉","description":"球员卡片的「生涯荣誉」显示联盟杯赛MVP的获奖次数和赛季。已有存档中保存的获奖记录也可查看。","category":"新增功能"},{"title":"轮换换位时同步互换分钟","description":"在阵容轮换中依次点击两名球员，换位时会一起对调设置分钟。首发和替补之间同样适用，0分钟也会参与互换。","category":"修复与优化"},{"title":"改善首页继续进度的读档等待","description":"继续上次进度时，如果另一页面占用存档导致第一次等待超时，游戏会自动重试一次。重试期间可以点击「结束读取」。","category":"修复与优化"},{"title":"改善加载恢复和弹窗兼容","description":"优化启动资源请求卡住时的恢复流程，并改善处理伤病轮换、查看交易来信和打开嵌套详情时可能出现的白屏或弹窗打不开的问题。","category":"修复与优化"},{"title":"保存失败后可保留当前操作","description":"部分赛季事件和选秀自动操作保存失败时，会暂停自动推进，保留已选决定或当前选秀进度，并提示重试。扩军建队及合同结算等操作保存失败时也会提示，当前页面进度会保留。","category":"修复与优化"},{"title":"改善浅色主题的低评分显示","description":"旧版浏览器也能清楚显示浅色主题下低于60分的能力数字和条形。","category":"修复与优化"}],"closing":"已有存档可以继续游玩。自定义新秀池只用于符合条件且尚未生成的新秀名单，已经公布的名单会保留。"},{"date":"2026-11-17","dateLabel":"2026年11月17日","introduction":["本次更新完善退役与新秀生成规则，优化部分中国新秀成长，修复球员定位协商后的跨赛季保持，并优化头像、杯赛展示和启动体验。"],"items":[{"title":"修复反复提前续约导致老将长期不退役的问题","description":"提前续约加入退役意愿判断。决定不再续约的球员，不会因反复报价、加薪或更换球队而重新改变决定；已经签下的合同继续履行。","category":"修复与优化"},{"title":"修正部分旧存档的新秀潜力分布","description":"修复部分旧版新世代存档后续选秀中高潜力球员偏多的问题，统一按现有潜力档位概率生成。已经生成或公布的新秀名单保持不变。","category":"修复与优化"},{"title":"六名中国球员的新秀年龄固定为18岁","description":"后续生成的王治郅、巴特尔、孙悦、周琦、丁彦雨航、崔永熙新秀统一为18岁，已有球员不回改。","category":"修复与优化"},{"title":"优化六名中国新秀的成长配置","description":"新开的新世代生涯中，后续生成的王治郅、巴特尔、孙悦、周琦、丁彦雨航、崔永熙将调整技能分布、突出各自专项，让正常培养更有效。初始总评、潜力和身体数值保持，部分非核心技能相应调整；实际成长仍受出场、表现与伤病影响。已有存档和已生成名单不回改。","category":"修复与优化"},{"title":"修复协商后的球员定位在换季时恢复的问题","description":"自由市场签约、续约和提前续约球员，经协商同意或视频说服成功后的新定位，会在当前合同剩余期间保留，并同步后续赛季的定位承诺，避免换季被旧定位覆盖。合同薪资和期限不变。","category":"修复与优化"},{"title":"调整李凯尔的中文名与新秀潜力","description":"凯尔·安德森统一显示为“李凯尔”。后续生成的新世代新秀潜力调整为86，并同步成长上限；现役开档能力与潜力仍为73/73，已有球员数值保持。","category":"修复与优化"},{"title":"更新部分球员头像","description":"更换罗德曼、肖恩·坎普头像，调整坎普头像裁剪比例，并修正里奇·桑德斯头像背景，同步头像图集。","category":"修复与优化"},{"title":"改善启动等待与异常恢复","description":"完善启动资源等待和加载失败后的恢复处理，减少部分情况下长时间停留在加载页的问题；保留失败提示和重新加载入口，改善部分辅助功能异常对页面操作的影响。","category":"修复与优化"},{"title":"精简杯赛MVP展示","description":"调整杯赛MVP卡片的信息展示，精简重复内容，完善冠军球队名称的显示。","category":"修复与优化"}],"closing":"已有存档可以继续游玩。六人成长配置仅在新开的新世代生涯中影响后续生成的对应球员；其他年龄、潜力及对应成长上限调整沿用各自生效范围。定位协商修复作用于后续成功协商，退役意愿规则作用于后续提前续约，已签合同继续履行。已有球员数值、已完成比赛和历史数据保留。"},{"date":"2026-11-16","dateLabel":"2026年11月16日","introduction":["本次更新新增32队联盟杯赛，整理联盟页面，完善交易与合同规则，并优化球员资料、启动与保存体验。"],"items":[{"title":"新增联盟杯赛","description":"32队分为8个小组，每组4队进行单循环，小组第一晋级淘汰赛。常规赛每队仍为82场，决赛额外进行一场，不计入常规赛排名和个人赛季统计；杯赛冠军、MVP和最佳阵容单独记录。新开生涯首季启用，已有存档从下一赛季开始参加。","category":"新增功能"},{"title":"联盟页面更清楚","description":"联盟入口整理为联盟排名、数据荣誉、赛事中心、球员动态四组。数据荣誉按奖项竞争、赛季榜、历史榜三项同排，杯赛和赛程集中在赛事中心；各组保留上次选择。统一页面标题高度，压缩伤病概览和关注球员行，关注头像改为方形。","category":"修复与优化"},{"title":"完善交易搜索与操作体验","description":"拟真挂牌可选择综合建队、即战力、年轻潜力、选秀权、释放薪资5种回报方向；指定目标最多3套方案，更重视阵容适配和筹码质量。修复还价遗漏，补充对方球队的轮换、未来和合同收益，完善拒绝建议和经理回复口吻。详情增加年龄、双方交易前后工资帽空间、对方薪资表及配平金额说明。修正首轮新秀第三、四年选项执行后的保障工资，非保障合同按日期、保障和已赚薪资配平，处理六月衔接；裁员和交易共用合同数据。本队非卖品仅在常规赛限制交易，休赛期、选秀和季前不受该标记限制；留队进入常规赛后恢复保护，当季解锁资格和对方核心保护保持。修复全屏返回按钮遮挡，调整回报方向间距。仍须满足交易条件，不保证每笔都有还价；经典搜索规则保持。","category":"修复与优化"},{"title":"调整部分中国球员资料","description":"李凯尔国籍更正为中国。后续生成的新世代历史新秀初始能力/潜力调整为：王治郅66/76、巴特尔62/72、孙悦62/72、周琦65/75、丁彦雨航62/72、崔永熙60/70；其中王治郅、巴特尔、孙悦、周琦的生成年龄为18–20岁。上述初始数值和年龄不回改已有球员或已公布名单。","category":"修复与优化"},{"title":"改善扩军选秀与模拟保存响应","description":"减少扩军选秀搜索、位置筛选和球队面板操作中的重复处理，继续优化新世代连续模拟、数据同步与后台保存的页面响应。保存频率、完整校验和原有暂停规则保持。","category":"修复与优化"},{"title":"改善存储空间不足时的保存恢复","description":"存储空间不足时，继续清理当前槽位可淘汰的旧恢复点，并完善写入失败后的回滚，减少保存反复卡住的情况。主存档和其他槽位保留。","category":"修复与优化"},{"title":"修复部分轮回球员生成报错","description":"修复部分24维存档生成轮回球员、进入新赛季时的巅峰评分校验报错，保留已有球员能力和历史记录。","category":"修复与优化"},{"title":"改善旧版设备兼容与加载恢复","description":"修复部分旧版系统中启动、排行榜和反馈提交的兼容问题，完善资源等待期间的恢复处理，并改善深色全屏模式的顶部显示。仍遇到加载或运行异常时，可通过反馈入口提交问题。","category":"修复与优化"}],"closing":"已有存档可以继续游玩。联盟杯赛从旧档下一赛季启用；球员初始能力和潜力调整仅影响后续生成的对应新世代历史球员。已完成比赛和历史数据保留。"},{"date":"2026-11-15","dateLabel":"2026年11月15日","introduction":["本次更新新增联盟历史榜、GOAT积分和国籍筛选，补齐管理统计，并改善模拟保存及加载体验。"],"items":[{"title":"新增联盟历史榜单","description":"「联盟 → 数据榜单」分为赛季榜和历史榜。赛季六项数据各展示前5，历史总得分等11项数据与荣誉各展示前20；在役、退役球员均可上榜。仅累计更新后本存档内全联盟的新数据与荣誉，技术数据只计常规赛，更新前的记录不补算。","category":"新增功能"},{"title":"新增GOAT积分榜","description":"历史榜默认展示GOAT前50。MVP每次加10分、FMVP加8分、冠军加5分、一阵加3分、全明星加1分，常规赛累计数据另行加分。积分持续累加、不设上限，三分命中不额外加分；可在榜单内查看完整规则。","category":"新增功能"},{"title":"选秀与自由市场增加国籍筛选","description":"新秀名单、关注、选秀板、选秀当日候选，以及常规赛和休赛期自由市场均可按国籍查找球员，并与原有姓名、位置等筛选组合使用。中国固定为第一个具体国家，资料不明时显示“未知”。","category":"新增功能"},{"title":"管理概览统计更完整","description":"球员赛季概览补充罚球命中率、失误、前板、后板、犯规和场均出手，左右滑动即可查看。同步调整球员卡与赛后数据中心的统计顺序；旧记录缺少的数据仍显示“—”，部分记录会标明覆盖场次。","category":"新增功能"},{"title":"修复部分苹果设备的拟真交易询价报错","description":"修复旧版系统中获取拟真交易报价、向对方经理询价时可能出现的运行错误。交易估值、薪资匹配和成交条件保持原有规则。","category":"修复与优化"},{"title":"减少连续模拟与自动保存的集中等待","description":"优化交易截止日前电脑球队的交易搜索与主动报价处理，并调整大历史存档的同步、榜单查询和后台保存调度，让页面在保存期间有机会响应操作。保留原有报价与来信暂停规则、保存频率和完整校验。","category":"修复与优化"},{"title":"优化续约和自由市场操作响应","description":"减少合同薪资页编辑续约报价、打开非卖品设置，以及常规赛自由市场筛选和排序时的重复处理。常规赛自由市场的姓名搜索、国籍和排序集中在同一行，国籍与排序菜单宽度保持一致。","category":"修复与优化"},{"title":"改善加载和设置弹窗兼容性","description":"启动资源长时间未就绪时，会尝试恢复对应资源，并处理迟到的配置；仍失败可重新载入。修复部分设备关闭非卖品等设置弹窗时可能出现的页面异常。","category":"修复与优化"},{"title":"修正部分球员资料与头像","description":"小达里厄斯·阿卡夫后续新生成时的初始能力调整为77，按现有公式计算潜力为90；已有球员不回算。基里连科的国籍更正为俄罗斯，并修正内线杰森·威廉姆斯的头像，避免与同名控卫“白巧克力”混淆。","category":"修复与优化"}],"closing":"已有存档可以继续游玩，已完成的比赛和历史统计保持原样。历史榜从更新后的新比赛或新荣誉开始累计，不补算此前记录，也不补造旧记录中缺失的数据。"},{"date":"2026-11-14","dateLabel":"2026年11月14日","introduction":["新增休赛期突破特训，补充球员资料和比赛统计，并优化年轻球员培养与保存体验。"],"items":[{"title":"新增休赛期突破特训","description":"新世代生涯在选秀后休赛期可培养本队已签约球员，不限本届新秀。首次须24岁及以下、潜力低于80；玩家球队每赛季只能选1人，看1次视频安排特训，AI不参加。完播后显示“已安排”，开季通知结果。球员有连续三个年度机会，错过不补；已开启者超过年龄或潜力门槛仍可继续。普通潜力依次＋4、＋3、＋2，中国籍依次＋6、＋5、＋4，并获得少量能力成长（普通最多约1点、中国籍最多约2点）。","category":"新增功能"},{"title":"球员资料增加国籍","description":"球员详情和球探资料可查看中文国籍，已有存档也能显示。资料不明的球员显示“未知”。","category":"新增功能"},{"title":"补充篮板与犯规统计","description":"比赛及生涯数据增加前场篮板、后场篮板和个人犯规。旧比赛缺少明细时显示“—”，六犯离场规则保持原样。","category":"新增功能"},{"title":"调整部分历史球员资料","description":"姚明新秀能力80、潜力96；大卫·韦斯特能力72；利文斯顿潜力82。拉塞尔和库里的巅峰参考调整为99，库里现役开档能力仍为93。仅影响后续生成的球员，已有球员不变。","category":"修复与优化"},{"title":"提高35名历史新秀的初始能力","description":"调整阿里纳斯、怀特塞德等35人的新秀起点，例如拜纳姆67→71、潜力仍为87。潜力与巅峰上限保持，仅影响后续生成的新世代历史新秀。","category":"修复与优化"},{"title":"电脑球队更重视年轻球员","description":"电脑球队可同时下放2人，优先培养高潜力球员，并在阵容允许时给年轻球员更多出场机会。","category":"修复与优化"},{"title":"下放球员受伤也会提醒","description":"发展联盟球员受伤后也会出现处理提示，可选择普通康复或观看视频接受专家会诊。","category":"修复与优化"},{"title":"返回首页前显示保存进度","description":"返回首页前先保存到本地，失败时可以重试或继续游戏。云备份仍需手动上传。","category":"修复与优化"},{"title":"休赛期进度更清楚","description":"切换年度和进入选秀前休赛期时显示处理进度；等待超过30秒可提交反馈。","category":"修复与优化"},{"title":"连续模拟会定期保存","description":"累计完成10场本队比赛或推进20个游戏日，先达到哪个就触发后台周期保存。关键操作仍会照常保存。","category":"修复与优化"}],"closing":"已有存档可以继续游玩。球员数值调整不回填已生成名单，已完成的比赛和历史统计保持原样。"},{"date":"2026-11-13","dateLabel":"2026年11月13日","introduction":["本次更新新增本队非卖品设置，扩展下放培养名额，调整拟真交易中的高潜力估值和争冠补强，并改善球员详情、季后赛与大存档操作体验。"],"items":[{"title":"本队球员可设为非卖品","description":"在「管理 → 合同薪资」设置本队球员为非卖品，避免电脑球队将其列入主动交易报价。每队前2名可直接设置，从第3名起需看视频解锁该球员当季资格；当季取消后重新设置无需重复观看，跨季保留标记，球员离队后释放名额。需要将其放入交易方案时，请先取消非卖品设置。","category":"新增功能"},{"title":"下放培养扩至最多5人","description":"发展联盟下放名额由1个免费名额调整为2个基础名额，每次看视频可再增加1个，当季最多同时下放5人。召回后会释放在用名额，扩展名额当季有效；此前已解锁的额外名额继续保留，球员本人的下放资格仍按NBA球龄判断。","category":"修复与优化"},{"title":"高潜力球员更重视长期成长","description":"拟真交易根据公开潜力、当前能力和年龄评估长期成长，不再因现合同只剩一年就截掉后续成长价值。合同工资、保障和选项仍会影响合同收益，未来成长也不保证一定达到潜力上限。经典交易沿用原规则。","category":"修复与优化"},{"title":"争冠球队更愿用选秀权补强","description":"拟真交易中，拥有1名95+核心或2名90+球员的电脑球队，在核心可用且满足交易条件时，更倾向用选秀权和配薪筹码换取能提升当前轮换的球员。仍会核对薪资、名单和筹码回报，不会只因总评达标就强行成交。","category":"修复与优化"},{"title":"修复部分设备打开球员详情异常","description":"改善从交易和伤病信息打开球员详情时的兼容性。设备缺少部分文字测量或尺寸监听能力时，姓名显示会正常降级，避免文字适配影响整个页面。","category":"修复与优化"},{"title":"季后赛对阵与晋级提示更清楚","description":"季后赛对阵图补充球队队徽，方便辨认对手；晋级结果弹框打开时不再默认选中确认按钮，减少操作干扰。","category":"修复与优化"},{"title":"提高浅色日历的可读性","description":"提高浅色主题中已完成赛程日期与胜场文字的对比度，让赛程信息更容易辨认。","category":"修复与优化"},{"title":"改善大存档操作与保存响应","description":"减少交易筹码选择、联盟动态搜索和生涯详情中的重复处理，并调整大存档读取、传送和保存的调度，减少部分操作的连续阻塞。保存未完成或失败时保留明确状态和重试入口。","category":"修复与优化"}],"closing":"已有存档可以继续游玩。拟真估值调整会影响后续报价，经典交易保持原规则；已有球员能力、已完成赛果和成交历史不回算。"},{"date":"2026-11-12","dateLabel":"2026年11月12日","introduction":["本次更新新增下放培养和自由市场报价对比，补充历史球员，并优化保存响应、手机页面适配与队史展示。"],"items":[{"title":"新增发展联盟下放培养","description":"完整新世代生涯可在「管理 → 下放培养」安排轮换外球员参加发展联盟比赛，并随时召回。0～2年 NBA 球龄可免费下放，3年及以上可看视频解锁当季资格；每队有1个免费名额，可看视频增加1个。比赛数据单独记录，比赛经历参与赛季末成长，不即时增加能力或潜力。","category":"新增功能"},{"title":"自由市场可查看其他球队报价","description":"新增其他球队报价对比，按签约优先级展示年均薪资、实际保障金额、年限、承诺定位和末年选项，方便比较竞争条件，也可展开查看签约规则。","category":"新增功能"},{"title":"自由市场竞争报价优化","description":"进入自由市场首日即可看到电脑球队的初始报价。取消每名球员最多保留5份竞争报价的限制，避免有效报价仅因数量上限被淘汰；旧版因此被淘汰、且仍符合当前签约条件的报价可恢复参与竞争。最终签约仍需满足意愿、薪资和名单要求。","category":"修复与优化"},{"title":"历史球员池与头像更新","description":"新增普林斯，以及王治郅、巴特尔、孙悦、周琦、丁彦雨航、科尔·斯威德、韦尼恩·加布里埃尔和胡安·托斯卡诺-安德森的历史新秀资料与头像。伊戈达拉的模板和头像也有更新，新秀初始 OVR 为74、潜力为88。符合所选真人档位及入池条件时，可在后续选秀中出现。","category":"新增功能"},{"title":"调整特科格鲁和巴博萨的新秀能力","description":"后续生成的24维历史新秀中，特科格鲁初始 OVR 由61提高至71，巴博萨由68提高至72，对应初始能力同步提升。两人的潜力及巅峰能力上限保持，拜纳姆保持原值，已有球员不回填。","category":"修复与优化"},{"title":"轮换更尊重边缘球员定位","description":"自动安排轮换时，在位置适配相同的情况下，定位为「边缘球员」的球员优先让位于其他可用人选，再比较能力。仍会兼顾位置覆盖、健康与合同约定的出场时间。","category":"修复与优化"},{"title":"普通操作后台保存更顺畅","description":"关注球员、普通轮换调整和编辑交易筹码时，等待保存期间可继续操作，并尽量合并为最新进度保存，减少重复等待。界面区分「待保存」「自动保存中」与「已保存」；交易确认、奖励和阶段切换仍会确认保存完成。","category":"修复与优化"},{"title":"优化手机顶部与底部操作区","description":"适配虎扑全屏页面的顶部安全距离，减少页头被遮挡的情况。选秀准备页和扩军交易桌保留底部操作区，中间名单与报价独立滚动，方便在小屏幕上操作。","category":"修复与优化"},{"title":"增加退出与反馈社群入口","description":"首页和游戏设置增加退出入口，确认后退出游戏页面，退出仅保留已保存进度。问题反馈中可直接展开玩家交流群二维码，便于交流和补充问题信息。","category":"新增功能"},{"title":"退役球衣效力时间更简洁","description":"退役球衣墙的效力时间改为起止年份，例如「2141—2164」，减少长赛季文字被截断。完整效力赛季仍可在详情中查看。","category":"修复与优化"}],"closing":"已有存档可以继续游玩。球员能力调整仅用于后续生成的新秀，已有球员及已完成赛果保留。"},{"date":"2026-11-11","dateLabel":"2026年11月11日","introduction":["新世代球员现在可以更换位置。本次更新还调整了伤停时的排阵和电脑球队的轮换，补充了 2026 届新秀头像，并改善了交易、选秀和启动体验。"],"items":[{"title":"新世代球员可更换位置","description":"在本队球员的「球员设置 → 修改球员位置」中，可以先预览总评，再看视频更换一个主位置或副位置。已有主副位置仍可免费互换。轮换编辑和赛前对位按实际首发位置显示 OVR，调换首发时即时更新；新增位置的表现取决于对应能力，未登记的位置仍有错位影响。","category":"新增功能"},{"title":"手动轮换在伤停期间临时自动排阵","description":"原方案中有首发或安排了分钟的球员无法出场时，系统会临时重排首发、替补和出场时间。等原方案里的轮换球员都能出场后，会自动恢复手动安排。","category":"修复与优化"},{"title":"电脑球队轮换更重视能力和位置覆盖","description":"首发位置适配相近时，电脑球队优先选择总评更高的球员。安排替补时，电脑球队会兼顾合同约定的出场时间和各位置的人手，尽量保留可用的替补中锋。常规赛中，公开潜力为 A+ 或 S 的新秀会获得轮换竞争加分。","category":"修复与优化"},{"title":"补齐 7 名 2026 届新秀头像","description":"为杰克·卡伊尔、泰勒·尼克尔等 7 名新秀补齐头像，球探列表和球员详情均可查看。","category":"修复与优化"},{"title":"调整新世代杨瀚森的开局能力","description":"新开的 24 维生涯中，杨瀚森初始总评为 74、潜力为 86，成长更侧重传球策应和防守篮板。","category":"修复与优化"},{"title":"自由市场结束时清理剩余薪资占位","description":"自由市场结算完成后，系统会放弃本队仍占用薪资空间的自由球员签约权，释放相应占位。工资帽明细会提前提示。","category":"修复与优化"},{"title":"修复旧档首次选择交易模式卡住","description":"旧档首次选择拟真或经典交易时，可以正常确认保存。已完播、尚未兑现的交易奖励会保留，之后完成同类操作时可直接使用。","category":"修复与优化"},{"title":"优化操作响应和启动恢复","description":"减少交易报价首屏、目标球员搜索、乐透揭晓和球探列表滚动时的重复处理。游戏入口未能正常初始化时会自动重试一次，仍失败时可手动重载。","category":"修复与优化"}],"closing":"已有存档可以继续游玩。轮换和比赛相关调整适用于后续比赛，已完成赛果保留。"},{"date":"2026-11-10","dateLabel":"2026年11月10日","introduction":["本次更新将本地存档扩至 10 个槽位，调整了云备份方式，加快了交易询价和长生涯操作，并更新了后续选秀的潜力概率。"],"items":[{"title":"本地存档扩至 10 个槽位","description":"新增 07–10 号本地槽位。原有 01–06 号存档可以继续游玩，恢复云档时也可以选择任一本地槽位。","category":"新增功能"},{"title":"云备份改为手动上传","description":"游戏仍会自动保存到本地。要备份到云端，请在首页或游戏内的本地存档槽位点击「上传到云端」。显示「本地有更新」时，表示本地进度比云备份更新。若两台设备的进度发生冲突，可选择上传本地进度或恢复云端进度。","category":"修复与优化"},{"title":"云档上传和恢复进度更清楚","description":"上传、下载和校验时会显示当前步骤及进度，恢复后会提示正在载入哪个槽位。同时减少首次上传和恢复过程中的重复读取。","category":"修复与优化"},{"title":"优化长生涯的保存和页面响应","description":"减少进入选秀前阶段时的重复存档校验，并优化长档里的关注球员搜索和生涯总览。离开游戏页面时会回收空闲的模拟资源。","category":"修复与优化"},{"title":"加快拟真和经典交易询价","description":"两种模式都减少了「获取报价」「向对方经理询价」及编辑方案后请求还价的等待时间，尤其是多名球员参与的交易。估值、报价和成交规则沿用原有口径。","category":"修复与优化"},{"title":"提高后续选秀的 S 档潜力概率","description":"尚未生成的常规选秀届次中，S 档从 1% 提高到 1.5%，D 档从 17% 调整为 16.5%，其余档位比例照旧。","category":"修复与优化"},{"title":"修正奥多姆的位置","description":"拉马尔·奥多姆的默认位置调整为主大前锋（PF）、副小前锋（SF）。已有新世代存档中，仍使用旧默认位置的奥多姆会在读档时同步修正，手动设置的位置会保留。","category":"修复与优化"},{"title":"补充头像和排行榜兼容","description":"为里奇·桑德斯补充球探列表及球员详情头像，并改善部分虎扑账号读取和同步排行榜时的兼容性。","category":"修复与优化"}],"closing":"已有存档可以继续游玩，无需重新开档。"},{"date":"2026-11-09","dateLabel":"2026年11月9日","introduction":["本次更新调整首轮新秀工资和年轻球员交易估值，也补充了休赛期日期提示，并修复了一处开季报错。"],"items":[{"title":"首页新增反馈入口","description":"可在首页打开反馈入口查看说明。","category":"新增功能"},{"title":"休赛期日期提示","description":"休赛期顶栏会显示当前游戏日期，并按阶段提示距离选秀或开赛的天数，以及自由市场进度。","category":"新增功能"},{"title":"首轮新秀工资调整","description":"首轮新合同参考 NBA 新秀工资表，按顺位计算，并随当届工资帽增长。前两年全额保障，第三、四年为球队选项，第四年涨幅按顺位计算。已签合同继续按原金额执行。","category":"修复与优化"},{"title":"年轻高潜球员估值优化","description":"提高 20 岁以下球员公开潜力在交易估值中的权重，让合同期内的成长空间更充分地反映在报价中。","category":"修复与优化"},{"title":"修复季前赛开季报错","description":"修复生成 P.J. 布朗时可能出现的位置校验错误。新秀按原有能力数据初始化，成品位置为主 PF、副 C，季前赛补齐名单后可以继续开季。","category":"修复与优化"}],"closing":"已有存档可以继续游玩，无需重新开档。"},{"date":"2026-11-08","dateLabel":"2026年11月8日","introduction":["本次更新针对近期反馈，重点优化季后赛、阵容轮换和交易体验，感谢大家帮助我们发现问题。"],"items":[{"title":"新世代季后赛优化","description":"适度降低24维季后赛的随机波动，让阵容实力发挥得更稳定，同时保留爆冷的可能。AI球队默认采用两个进攻点，与玩家默认设置一致；玩家仍可解锁第三进攻点。","category":"修复与优化"},{"title":"自动轮换随阶段调整","description":"自动模式默认采用常规赛10人、季后赛8人轮换，明确自定义的轮换人数保留。球队详情同步显示当前阶段的出战安排，轮换说明也增加了重点标色。","category":"修复与优化"},{"title":"修复轮换与分钟异常","description":"修复休赛期调整轮换时报错，以及部分比赛没有加时却出现异常出场分钟的问题。","category":"修复与优化"},{"title":"历史球员位置同步修正","description":"韦德调整为SG/PG，麦迪和吉姆·杰克逊调整为SG/SF，P.J.布朗调整为PF/C。符合条件的新世代已有存档在读档时同步修正，无需重新开档；保留玩家手动调整的位置、属性、成长和历史记录。","category":"修复与优化"},{"title":"交易报价搜索优化","description":"优化选秀权补差、降签交易及球员与选秀权混合报价，尽量寻找回报更好的可行方案。对方仍会根据球队需求和交易规则决定是否接受。同步改善询价等待和异常提示，计算超时后可调整筹码重试。","category":"修复与优化"},{"title":"交易后可裁新援腾位","description":"拟真交易遇到名单超额时，除了现有球员，也可选择本次交易得到的新援裁员腾位。例如1换3后，可按所需名额选择裁掉其中的新援。确认成交后才会执行，剩余保障工资由我方承担；交易仍须按完整筹码通过薪资配平和名单校验。","category":"修复与优化"},{"title":"交易信息更直观","description":"球员与选秀权展示具体估值，双方资产价值差、球队OVR变化及薪资条件更清楚，并优化资产价值说明的排版。","category":"修复与优化"}],"closing":"已有存档可以继续游玩，无需重新开档。本次比赛调整只影响后续比赛，已完成的赛果与历史数据保留。"},{"date":"2026-11-07","dateLabel":"2026年11月7日","introduction":["本次更新对照上一版交易系统继续完善交易体验：新增两种交易模式，并优化拟真交易的询价搜索、报价解释、谈判确认和交易中的保护流程。","拟真交易会更重视能力、潜力、合同与球队需求，适合希望体验更接近真实 NBA 经营难度的玩家；经典交易保留第一版的节奏和规则，方便不同偏好的玩家自行选择。"],"items":[{"title":"交易模式自由选择","description":"新开生涯时可以选择拟真交易或经典交易，之后也能在设置中按生涯切换。模式会随存档保存；切换后未成交报价、编辑中的方案和待处理来信会失效，已完成交易、球队进度和历史记录保留。","category":"新增功能"},{"title":"报价结果和无报价原因更清楚","description":"在当前搜索范围内，只要对方球队愿意接受且通过全部硬规则，就尽量展示对方能给出的最高回报；即使我方收到的资产估值更低，也会展示可行方案，由玩家决定是否成交。没有报价时，会尽量说明是价值、薪资、选秀权限制还是暂时没有找到合适组合。","category":"修复与优化"},{"title":"双方同意后不再重复看视频","description":"合法报价已经通过交易规则、双方都同意后，可以直接确认成交，不会再重复要求观看视频。只有涉及非卖品或前三顺位等受保护资产时，仍按提示通过激励视频争取对应资格。","category":"修复与优化"},{"title":"交易操作与页面响应优化","description":"减少交易询价、报价计算和详情展示中的重复处理，也同步改善长生涯、季后赛、球探和启动恢复时的部分等待与异常处理，让连续操作更稳定。","category":"修复与优化"}],"closing":"已有存档可以继续游玩，无需重新开档。旧存档首次进入时如果还没有交易模式记录，会先请你选择；之后可在设置中修改。切换模式不会重算球员能力、合同、比赛结果或历史交易，但当前未完成的交易方案需要重新询价。"},{"date":"2026-11-06","dateLabel":"2026年11月6日","playerMessage":{"title":"关于这次交易引擎优化","paragraphs":["关于这次交易引擎的优化，我个人觉得目前的交易价值整体上没有太大问题，但也不排除还存在一些不合理的情况。毕竟交易涉及的因素和随机性很多，我在测试过程中也很难覆盖到所有情况。","做这款游戏的初衷，就是希望它能像 NBA 2K 一样，尽可能还原真实 NBA 的交易逻辑和球队运营体验。但游戏终究是由数据和规则构成的模拟，不可能完全复刻现实中的每一种情况。","后续我也会持续关注大家的反馈和评论，如果发现确实存在不合理的交易，我会继续调整和优化，争取让交易系统越来越真实、合理。","如果遇到你认为不合理的交易，欢迎到我在虎扑发布的最新帖子下留言反馈，也可以贴上截图，注明当前选择的交易模式，说明交易双方的筹码、球员和合同情况，以及你觉得不合理的地方，方便我核对和排查。","考虑到部分玩家可能还在使用第一版交易系统，为了避免不同版本的情况混在一起，建议大家从2026年11月7日起再集中反馈。反馈前请确认使用的是更新后的游戏，并尽量提供更新后新产生的交易案例。","也感谢大家愿意认真体验游戏、提出建议，希望能和大家一起把这款游戏慢慢打磨得更好。"]},"introduction":["本次更新重点完善交易和球队经营，加入报价分页与交易腾位，并调整常规赛补员、休赛期自由市场和最佳第六人评选。","优化“搜索报价”和“获取报价”：在对方愿意接受且符合交易规则的前提下，尽可能展示价值更高的报价；即使我方收到的回报低于送出筹码，也会显示可行方案，由你决定是否成交。"],"items":[{"title":"交易模式可选","description":"新开生涯可选择拟真交易或经典交易，之后也可在设置中切换。估值、询价、还价、刷新和AI交易会按所选模式运行。切换会清除未成交报价，已完成交易与生涯进度保留。旧档首次进入需确认模式。","category":"新增功能"},{"title":"交易报价分页","description":"使用我方筹码询价时，每页最多显示3支球队，每队1份方案。有更多报价时，可观看视频解锁下一批。已解锁的页面可以免费往返，之前的报价和谈判进度会保留。","category":"新增功能"},{"title":"不等人数交易支持腾位和还价","description":"例如用两名球员换一名球员，详情会提示哪一方需要腾位。原方案未谈妥时，对方会优先尝试保留你指定的球员，再调整配套筹码。每份新方案都会重新核对薪资和名单。需要我方裁员时，由你选择人选，确认成交后才会执行裁员和交易。","category":"新增功能"},{"title":"常规赛缺员提醒与自动补员","description":"正式名单暂时只有12或13人时，页面会显示剩余补员天数。连续缺员满14个游戏日，或当季累计缺员达到28天后，系统会自动签下一年底薪替补，补齐至14人，并通过球队消息通知你。","category":"新增功能"},{"title":"球员和选秀权估值调整","description":"球员估值以当前能力和表现为主，结合合同期内的成长、衰退、伤停和薪资负担。选秀权也会结合预计签位及已公开的新秀质量估价。","category":"修复与优化"},{"title":"交易信息更清楚","description":"球员和选秀签统一用星级展示交易价值，具体分数在「资产价值说明」中查看。等待期球员会显示具体可交易日期。薪资不匹配时，详情会提示哪一方未通过及可调整的筹码方向。","category":"修复与优化"},{"title":"休赛期 AI 优先处理球星签约","description":"AI 会优先考虑总评90及以上的自由球员。球员连续60个市场结算日未收到合格报价时，有合适条件的球队会尝试开出短约。","category":"修复与优化"},{"title":"明确最佳第六人资格","description":"球员须实际出战至少65场常规赛，且替补出场次数多于首发次数。此规则适用于尚未颁发的奖项。","category":"修复与优化"},{"title":"改善云存档和手机操作","description":"云端写入回执缺少部分信息时，游戏会读取刚写入的内容进行确认。调整选秀、赛季和接手球队页面的底部操作区，减少按钮被手机界面遮挡的情况。","category":"修复与优化"}]},{"date":"2026-11-04","dateLabel":"2026年11月4日","playerMessage":{"title":"关于球员赛季场均数据","paragraphs":["球员的得分、篮板和助攻由能力特点、出场时间、进攻点设置、队友配置及伤病状态共同决定，并非按总评或现实生涯数据固定生成。同一名球员在不同阵容中，可能承担更多得分任务，也可能更多参与组织，因此赛季场均会有所不同。","本轮优化完成后，接下来几次更新将暂缓球员与比赛表现方面的调整，重点放在交易、合同等核心系统的完善上。等各项核心引擎整体稳定、主要问题得到解决后，再考虑在此基础上增加新的游戏模式。","感谢大家一直以来的支持！"]},"introduction":["本次调整历史新秀与成长表现，让高潜力真人新秀更多迎来新面孔；继续优化新世代比赛，并改善连续操作、自动保存与年度切换体验。"],"items":[{"title":"高潜力真人新秀优先新面孔","description":"S、A+、A 级真人新秀分别按累计名额采用“80% 首次、20% 轮回”的分配，让尚未进入本生涯联盟的球员获得更多机会。同等级池不足时相互补充，退役冷静期继续保留；已生成名单不变。","category":"修复与优化"},{"title":"历史新秀与成长校准","description":"更新历史真人新秀的初始能力、巅峰参考与成长上限，采用有资料支持的 NBA 首秀年龄，更好地区分新秀期与成熟期。普通新世代生成新秀的入场年龄调整为18—20岁。","category":"修复与优化"},{"title":"伦德博格与弗拉格调整","description":"新世代新开档中，伦德博格初始总评调整为78、真实潜力调整为86，弗拉格初始总评87及当前各项能力保持、真实潜力提高至97，并同步校准两人的各项成长上限。已有存档与已生成球员不回填、不重算。","category":"修复与优化"},{"title":"球员赛季数据模拟校准","description":"优化新世代球员的得分、三分、篮板、助攻和抢断模拟与分配，改善部分数据过度集中的情况，让赛季场均更好地体现球员能力、场上职责、出场时间及阵容配置。调整用于之后的比赛，已有赛果与累计数据不重算。","category":"修复与优化"},{"title":"高频操作合并保存","description":"关注球员、调整普通轮换和交易筹码后立即生效，连续操作合并自动保存：停止操作2秒后发起保存，持续操作最多延后10秒。关键操作前先保存最新进度，保存失败保留重试。","category":"修复与优化"},{"title":"年度切换与存档优化","description":"减少检查点与新赛季保存对相同历史资料的重复处理，保留完整校验、失败重试和恢复保护，降低长生涯存档的重复处理开销。","category":"修复与优化"},{"title":"操作与运行流畅优化","description":"减少报价、续约、交易筛选和选秀确认的重复计算，优化部分设备上选秀与球探生成时的任务安排，减少界面显示中的重复处理。","category":"修复与优化"}],"closing":"已有存档可继续游玩，无需重新开档。除上述新生成球员调整外，既有球员当前能力、已生成新秀和历史赛果保留；适用历史球员的后续成长会采用更新后的上限保护。请等待“已保存”后再退出，年度切换耗时仍会随存档规模和设备性能变化。"},{"date":"2026-11-02","dateLabel":"2026年11月2日","introduction":["本次新增历史真人生涯与历届选秀查看，精简历史球探报告，并改善多页面同时使用时的存档等待与错误处理。"],"items":[{"title":"历史真人前生今世","description":"历史真人球员卡片新增“前生今世”，可切换已记录的游戏生涯，查看保留的累计数据、场均数据与荣誉。旧档当前生涯可显示为第1世，并区分进行中或已退役；现实生涯和此前未记录的世代不补录。","category":"新增功能"},{"title":"历届选秀名单","description":"选秀中心新增“历届选秀”，按年份查看全联盟当届顺位、轮次、球员位置及当时选中球队。球员卡片点击选秀年份或总顺位，也能打开同届名单；从之后完成的选秀开始记录，旧届缺失时明确提示。","category":"新增功能"},{"title":"历史球探报告减重","description":"移除“历届报告”，不再累计完整历史球探报告；当届考察照常，已获得的潜力结论保留。旧完整报告在下次正常保存时从主档去掉，旧备份仍可能暂时保留相关资料，存储空间会随后续清理逐步释放。","category":"修复与优化"},{"title":"多页面存档等待优化","description":"改善同时打开多个游戏页面时，后台自动云同步读取与前台保存之间的等待协调；保存前的保护性备份若因等待超时失败，会先提示重试，避免继续推进后再次等待。不能保证所有设备上的保存超时都消失。","category":"修复与优化"},{"title":"本地存档错误处理修复","description":"修复部分浏览器在数据库请求尚未结束时读取错误信息、再次引发异常的问题，保留原有保存失败提示、重试与错误反馈。异常反馈也会更清楚地区分等待中的操作与观察到的占用操作。","category":"修复与优化"}],"closing":"本次不改变球员能力、成长、选人和比赛规则，不重算历史赛果。若仍遇到异常，请通过问题反馈附上操作过程与诊断信息。"},{"date":"2026-11-01","dateLabel":"2026年11月1日","importantNotice":"旧生涯在赛季结束、进入休赛期时会整理历史资料，首次整理可能需要多等一会。请保持页面打开，等到保存完成后再退出。已有球员能力和历史赛果保留，无需重新开档。","introduction":["本次修复赛季中自动保存等待偏长的问题，完善历史资料整理与存档保护，优化24项能力下的比赛数据分配，并改善云同步和自由市场报价反馈。"],"items":[{"title":"赛季中自动保存优化","description":"修复赛季中自动保存时数据写入偏大的问题，改善续约等操作后的保存等待。保存仍会检查资料完整性，实际耗时会随存档大小和设备而变化。","category":"修复与优化"},{"title":"历史资料自动整理","description":"在赛季结束、进入休赛期时，单独整理往年的退休球员档案、球探报告、季后赛统计、奖项和交易详情，减少平时反复处理的资料。历史内容仍可查看；普通读档不触发首次整理。","category":"修复与优化"},{"title":"云同步请求优化","description":"减少同步前的多余等待，并调整连续同步时的请求节奏，减少频繁操作被拦截的情况。实际上传速度仍受网络和云服务影响。","category":"修复与优化"},{"title":"存档恢复保护","description":"加强保存失败、重试和备份恢复时的进度保护；只有确认新存档完整写入后，才清理临时恢复副本。","category":"修复与优化"},{"title":"24维比赛数据分配优化","description":"调整出手、助攻和篮板分配，缓解助攻过度集中、持球核心和策应内线助攻偏低的问题。结合球员能力、球权、职责与出场时间计算；已有球员属性保留，仅影响之后的24维比赛，历史赛果不重算。","category":"修复与优化"},{"title":"自由市场报价反馈","description":"报价未成交时，通知与报价卡片更清楚地区分意愿不足、名单或角色限制、薪资预算变化、被其他球队签下及原队匹配等实际原因，方便调整下一次报价。","category":"修复与优化"},{"title":"赛前激励备战加成提高","description":"完整观看激励视频并选择进攻或防守后，下一场按所选方向获得更高备战加成：常规赛约每100回合多得或少失1.5分，季后赛约2分。加成只作用于下一场，不代表固定胜率提升。","category":"修复与优化"}],"closing":"本次不转换球员能力体系，也不重算已完成比赛。首次历史资料整理可能较慢，请在页面提示保存完成后再退出。"},{"date":"2026-10-31","dateLabel":"2026年10月31日","importantNotice":"24项能力体系刚上线，部分球员的赛季数据可能会出现异常或不合理的情况。遇到问题请及时通过游戏内“玩家反馈”告诉我，并说明球员、赛季和具体异常，我会根据反馈及时排查和调整。感谢大家的理解与支持。","introduction":["本次新增深色与复古报纸浅色主题切换，调整新世代出手、助攻与篮板分配，补充部分历史球员能力资料，并修复云档删除、改善长生涯操作响应。"],"items":[{"title":"深浅主题切换","description":"游戏设置中可一键切换深色与复古报纸浅色主题，首页、主要页面、弹框和排行榜同步适配。主题偏好独立保存，不影响生涯进度与存档。","category":"新增功能"},{"title":"新世代出手分配","description":"结合投射、突破、背身能力和进攻倾向分配出手机会，更好地区分得分手、组织核心和防守篮板专长球员，继续考虑实际出场时间、角色与进攻点设置。","category":"修复与优化"},{"title":"组织核心与助攻分配","description":"结合24项能力中的传球精度、进攻判断及实际出场与出手情况分配助攻，进一步区分组织核心和高传球能力的得分手；多名组织者按实际阵容分享机会，保留正常比赛波动。","category":"修复与优化"},{"title":"篮板专长与机会分配","description":"分别依据进攻篮板与防守篮板能力分配机会，减少仅因位置标签造成的额外偏差，让篮板专长更能体现在比赛中。得分、助攻和篮板均按通用能力规则分配，不按指定球员身份保底。","category":"修复与优化"},{"title":"部分历史新秀能力资料","description":"补充贾巴尔、张伯伦、比尔·拉塞尔、巴克利、雷吉·米勒、比卢普斯和易建联的历史能力参考，并优化缺少完整参考时的能力生成。仅影响后续新生成球员，已有球员和已生成名单保留。","category":"修复与优化"},{"title":"云存档删除修复","description":"修复云空间接近满额时可能无法准备删除的问题，完善删除成功后的记录移除与列表刷新失败提示。本地进度和其他云档保留。","category":"修复与优化"},{"title":"长生涯操作响应优化","description":"减少球队通知分类、交易与续约记录切换时的重复处理，优化比赛结果更新和自由市场列表刷新，改善长生涯中的浏览与操作响应。","category":"修复与优化"}],"closing":"已有存档可继续游玩，无需重新开档。比赛调整仅用于后续的新世代模拟，经典比赛算法保持；已有球员能力、成长记录、历史赛果和累计统计不重算。删除云档请使用更新后的版本，退出前请等待“已保存”。"},{"date":"2026-10-30","dateLabel":"2026年10月30日","importantNotice":"为避免误选“使用真实球员身份、但能力随机生成”模式后，对球员身份和能力产生混淆，本次取消这项机制。后续真人新秀按真人模板和原有规则生成，虚拟新秀保留正常生成规则；曾启用该模式的生涯需要重新确认一次未来生成方式。已有球员、选秀名单和历史进度完整保留，旧随机球员会标注“历史随机·真人外观”，不会重置其数据。","introduction":["本次取消新秀能力随机模式，统一各阶段的新秀规则设置，优化存档读取、年度切换与历史正文恢复，调整新世代助攻分配和最佳阵容战绩权重，并修复生涯荣誉文字覆盖。"],"items":[{"title":"新秀规则与问题诊断","description":"设置中可选择优先使用真人模板的潜力档位，全部取消为全虚拟，扩军、接手球队、休赛期与常规赛入口保持一致。曾启用能力随机的旧生涯只需确认一次未来生成方式；球员卡区分真人模板、虚拟球员和历史随机·真人外观。已有球员和名单保留，问题反馈同步记录当前规则。","category":"新增功能"},{"title":"续约意愿与本队贡献","description":"结合争冠压力、球队竞争力和可核实的本队贡献评估续约意愿，改善功勋球员的续约判断；本队与外队候选使用一致的意愿规则，继续综合薪资、保障和角色等条件。","category":"修复与优化"},{"title":"交易谈判与草稿提示","description":"修复重新发起相同方案后，邀请继续谈判可能被旧记录拦截的问题；明确区分尚未发送的筹码草稿与对方已回复的方案，保存失败重试保留同次已确认的视频结果。交易估值与薪资、名单规则保持。","category":"修复与优化"},{"title":"存档读取与年度处理","description":"减少年度成长、历史正文校验和长生涯操作中的重复处理，改善存档列表等待，以及通知、关注和轮换等操作的响应。保留完整性校验和原有成长结果。","category":"修复与优化"},{"title":"历史正文恢复与进度保护","description":"完善历史正文缺失时的备份查找和精确恢复，优先保留较新进度，避免旧状态覆盖，并改善存储短暂断连的重试处理。只恢复校验通过的真实记录，不补造比赛历史。","category":"修复与优化"},{"title":"新世代助攻分配优化","description":"进一步缓解极端助攻过度集中的情况，同时保留正常组织核心的发挥空间。不设置固定上限，调整仅用于之后的新世代比赛，已完成比赛和累计统计保留。","category":"修复与优化"},{"title":"最佳阵容评选优化","description":"提高球队战绩在最佳阵容评选中的比重，继续综合个人表现与出勤，保留出场资格和符合条件的常规赛MVP一阵保障。已公布的阵容不重新评选。","category":"修复与优化"},{"title":"生涯荣誉展示优化","description":"修复生涯荣誉中总决赛MVP年份与场均数据重叠的问题，收紧留白，方便同时查看更多获奖赛季；球员卡片高度、文字大小和完整统计保持。","category":"修复与优化"}],"closing":"已有存档可继续游玩，无需重新开档。已有球员、已生成新秀、已完成比赛和已公布荣誉保留；新秀设置仅影响尚未生成届次。请等待“已保存”后再退出。"},{"date":"2026-10-29","dateLabel":"2026年10月29日","introduction":["本次新增场均出手与自由市场多日结算，优化新世代比赛的助攻分配、内线进攻与分差分布，修复AUTO轮换人数被重置的问题，并改善季后赛浏览体验。比赛平衡调整仅用于新世代，轮换和界面优化同时适用于经典存档。"],"items":[{"title":"球员场均出手","description":"球员赛季场均数据在罚球列后新增“场均出手”，查看运动战投篮出手次数，不含罚球。球员历季、球队数据及季后赛相关场均表同步展示并支持排序。","category":"新增功能"},{"title":"自由市场多日结算","description":"新增多日结算弹窗，默认结算3天（包含当天），提供3天、7天、30天和结算至市场结束的快捷选择，也可自行调整目标日期；底部操作和按钮风格同步优化。","category":"新增功能"},{"title":"新世代助攻分配","description":"结合传球、判断能力与进攻倾向分配助攻，更好地区分组织核心和持球得分手，改善低组织内线助攻机会过少的问题，并重新校准高水平传球手的发挥空间。","category":"修复与优化"},{"title":"新世代内线进攻","description":"优化篮下终结、背身与中投的机会分配，让内线更能发挥自身专项能力，并改善设置主要进攻点后的战术效果。调整按能力与战术统一生效，不针对指定球员。","category":"修复与优化"},{"title":"新世代比赛分差","description":"调整比分波动与季后赛分差分布，改善实力接近球队的比分过度集中在小分差的问题，保留正常的险胜结果。","category":"修复与优化"},{"title":"AUTO轮换人数保留","description":"保留玩家设置的轮换人数，伤病时按可用名单调整实际出场与分钟，复出后按原设置重新安排，避免被默认十人轮换覆盖。经典与新世代存档均适用。","category":"修复与优化"},{"title":"季后赛记录与滚动","description":"本队比赛结果和联盟近期比赛支持展开、收起，默认收起，模拟揭晓时自动展开。调整比赛记录与数据面板的滚动衔接，方便继续查看下方季后赛信息。","category":"修复与优化"},{"title":"年度切换处理","description":"减少年度成长中的重复计算，补充各处理步骤的进度和异常反馈。保持原有成长结果、保存校验与失败恢复流程。","category":"修复与优化"}],"closing":"已有存档可继续游玩，无需重新开档。新世代比赛调整作用于之后的模拟，已有赛果与累计统计不回算，经典比赛算法保持不变。请等待“已保存”后再退出。"},{"date":"2026-10-28","dateLabel":"2026年10月28日","introduction":["本次新增新秀规则设置、六项统计王与数据荣誉，集中完善季后赛对阵、系列赛比分和球队球员数据查询，并优化MVP评选、自由市场报价与续约判断。经典存档与新世代存档共同生效。"],"items":[{"title":"新秀规则设置","description":"季前进入常规赛前，可选择允许真实历史球员及现役轮回球员出现的潜力档位，或全部取消使用全虚拟新秀，并可开启能力随机模式。每个生涯确认一次，之后可在设置中查看；仅影响后续生成的新秀，已有球员与选秀名单保留。","category":"新增功能"},{"title":"统计王与数据荣誉","description":"新增得分王、篮板王、助攻王、抢断王、盖帽王和三分王，独立展示并保存赛季结果与球员生涯记录。三分王按常规赛三分总命中评选，其余五项按场均及出场资格结算；数据榜新增三分总命中榜。","category":"新增功能"},{"title":"系列赛详情与每场比分","description":"点击季后赛对阵图中的对阵，可查看系列赛大比分、每场比分、已保存的单场比赛详情和双方球员本轮场均，支持球队切换与排序。返回对阵图后保留原分区选择。","category":"新增功能"},{"title":"季后赛数据板与FMVP场均","description":"对阵图旁新增“季后赛数据”，可按赛季、球队查看整个季后赛的球员场均，淘汰球队继续保留，附加赛单独展示。FMVP结果与对应生涯记录补充总决赛场均数据。","category":"新增功能"},{"title":"各队球员场均数据","description":"球队弹窗新增“阵容 / 球员数据”切换，查看当前赛季球员效力该队期间的常规赛场均及命中率，包含有实际记录的已离队球员；支持排序和打开球员详情，保留原阵容与管理入口。","category":"新增功能"},{"title":"常规赛MVP与最佳阵容","description":"常规赛MVP综合个人表现、球队战绩与出勤评估，提高优秀战绩的贡献，并可查看评分分项。符合最佳阵容资格的常规赛MVP保底入选一阵，已公布的奖项和阵容保持原结果。","category":"修复与优化"},{"title":"单场MVP评分优化","description":"调整得分、篮板、助攻等贡献，降低抢断和盖帽的比重，并考虑未中投篮、罚球和失误，赛后页面增加评分说明。新规则用于后续常规赛和季后赛，历史比赛MVP保持不变。","category":"修复与优化"},{"title":"自由市场报价比较","description":"球员比较报价时更重视实际薪资与保障金额，报价接近时再结合球队、角色和个人偏好判断。保留正常签约条件和受限制球员匹配规则，已有合同条款不变。","category":"修复与优化"},{"title":"续约规则优化","description":"未满30岁的球星不再仅因多年无冠拒绝续约。合同选项阶段，本队到期续签的报价被拒或过期后可调整条件重新报价；仍须满足薪资、年限、名单和球员接受条件。","category":"修复与优化"}],"closing":"已有存档可继续游玩，无需迁档；已公布荣誉、历史比赛MVP和已有新秀名单保留。统计王从后续新的赛季结算开始记录，旧档缺失的历史比分或统计不补造。请等待“已保存”后再退出。"},{"date":"2026-10-26","dateLabel":"2026年10月26日","introduction":["本次新增新世代存档（24项能力与全新成长体系）、月度排行榜与月度荣誉界面，扩展赛季荣誉，补齐新开档鸟权与原队续签例外，并优化自由市场长期失业处理、球员卡与选秀操作。","旧八维生涯统一称为“经典存档 · 八维能力”。旧八维存档不会自动转换为24项，仍可继续游玩，沿用原能力与成长规则。暂不开放旧档迁移，主要是为避免现阶段迁移造成能力换算、成长记录或存档一致性问题；体验新世代存档需新开生涯。"],"items":[{"title":"新世代存档 · 24项能力","description":"新开生涯启用24项细分能力，按终结、投篮、组织、防守篮板、身体和判断分组查看，更清楚地了解球员的强项与弱项。存档卡片新增能力体系标记，区分新世代存档与经典存档。","category":"新增功能"},{"title":"全新成长与生涯曲线","description":"新体系结合实际出场时间、比赛表现、训练、健康与伤病结算成长和衰退，保留个人强弱项与成长上限；首季伤停也计入后续生涯记录。校准成长到比赛攻防的收益，并修正低能力普通新秀的总评额外放大；已有此类成长球员的显示总评可能回落，实际技能、潜力和历史记录保留。出场和培养提供成长机会，不保证每位球员都兑现潜力。","category":"新增功能"},{"title":"细分能力比赛表现","description":"新世代球员综合比赛实力与页面OVR对齐，球队基础实力按实际出场分钟加权球员OVR，高总评阵容通常更强。24项技能继续体现攻防特点、投篮、组织、篮板与体力，阵容适配、健康状态和临场发挥仍影响胜负。经典存档沿用八维规则；已有24项存档后续比赛采用新规则，不改能力、固定校准及成长记录，已完成比赛不重算。","category":"修复与优化"},{"title":"月度排行榜与荣誉墙","description":"新增月度积分、冠军数、冠军率榜及月度荣誉墙，可切换月榜与历史总榜，查看已归档月份的前三名。按北京时间自然月统计首次登记后的新增成绩，同账号采用本月积分最高的生涯，多个存档不累加；月冠军率需当月完成至少10季。配套月度服务启用后提供数据。","category":"新增功能"},{"title":"赛季荣誉扩展","description":"新增全明星MVP、东部决赛MVP、西部决赛MVP和最佳新秀第二阵容。全明星赛单独结算，分区决赛结束时公布对应MVP；奖项同步展示到联盟奖项、赛季结果、本队荣誉与球员生涯荣誉中，已结算的历史奖项不追补。","category":"新增功能"},{"title":"全明星与年度评选优化","description":"经典存档与新世代存档共同生效：全明星区分首发、替补和伤病递补，名单公布与表演赛分开结算；最佳阵容独立评选并完善出场资格，第六人按实际首发、替补次数评估。荣誉页面补充身份与规则说明，本队赛季荣誉卡片更简洁。已公布荣誉保持原结果，旧档缺失的逐场记录不追补，当季按过渡规则评选，下赛季完整统计。","category":"修复与优化"},{"title":"新开档鸟权校准","description":"新开生涯按球员合同与转队履历初始化鸟权及已完成赛季数，分别处理交易继承和认领连续性。已有生涯不重新初始化鸟权，也不覆盖累计年数。","category":"修复与优化"},{"title":"早鸟与非鸟续签","description":"新旧生涯后续新报价均可按早鸟、非鸟资格，在各自额度内超工资帽续签本队到期球员，仍须满足合同年限、选项和名单条件，球员也可拒绝。列表与报价弹窗显示资格、额度和限制。旧档当前周期保留原占位，新增占位从下个完整休赛期起计算；已有合同、历史及待结算报价原条款保留，不转换能力体系、不重置鸟权年数。","category":"新增功能"},{"title":"自由市场与退役优化","description":"让符合条件、长期无球可打的球员退出自由市场，保留高潜力球员的培养机会；完善高龄低能力球员的退役判断。修复历史薪资账单误阻止退出的问题，退役后继续保留账单、生涯、荣誉与历史记录。","category":"修复与优化"},{"title":"球员卡与选秀操作","description":"球员卡头部与底部操作保持可见，能力和简介在内容区域滚动；选秀页可整体滚动查看名单和详情，底部操作保持可用。改善长内容下的查看、返回和确认操作。","category":"修复与优化"},{"title":"自动轮换与页面细节","description":"自动匹配按页面OVR判断球员能力，保留主副位置、当前定位、伤停和签约分钟承诺；培养角色不再额外减分。所选轮换人数保留到常规赛与季后赛，伤停时临时调整、恢复后沿用原偏好。管理页球队适配按当前实际轮换、疲劳和位置计算；无法组成比赛轮换时标注名单估算。手动设置保留，存档标签统一放在球队名称下方。","category":"修复与优化"}],"closing":"已有合同、已完成比赛与历史统计不重算。新体系的长期联盟分布仍在持续校准，自由市场人数会随赛季变化。请等待“已保存”后再退出，遇到异常可通过游戏内反馈提供设备与操作信息。"},{"date":"2026-10-24","dateLabel":"2026年10月24日","introduction":["本次重点完善轮换设置、比赛模拟和存档管理：轮换人数可选，离开前提醒保存；修复球员比赛贡献与加时计算，并加入本地旧档找回和云档删除。沿用现有八维能力与成长衰退规则，已有存档无需重新开档。"],"items":[{"title":"可选择轮换人数","description":"在轮换页选择6—12人，再点击自动匹配并保存。人数随可出战球员数量限制，偏好在读档、跨年及模式切换后保留；伤停时临时调整，恢复后继续采用原偏好。","category":"新增功能"},{"title":"轮换未保存提醒","description":"修改分钟、首发、替补顺序或进攻点后，切换页面、读档或返回首页前，可选择保存并离开、放弃修改或继续编辑。只有保存成功才会离开；失败时保留草稿，避免比赛使用到未确认的安排。","category":"新增功能"},{"title":"比赛贡献计算修复","description":"修复部分球员属性接近99时成长反而降低攻防贡献的问题，并补齐可信真人旧档缺失的比赛校准来源。球星与阵容适配加成按实际出场分钟、疲劳和位置计算，减少极少出场球员带来的不合理加成。","category":"修复与优化"},{"title":"加时与季后赛优化","description":"加时继续考虑双方当场攻防、主客场与状态，按实际加时时长分配回合和出场时间；保留合理随机波动。季后赛按实际休息天数恢复疲劳，比赛仍受阵容、分钟与状态影响，高总评不保证必胜。","category":"修复与优化"},{"title":"真人新秀混合抽取","description":"后续新生成的名单中，现役球员退役轮回与历史真实球员按相同潜力档位混合、按等待时间加权抽取，不再优先或预留现役轮回名额。原有资格、冷却和去重规则保留；已生成及已公布的新秀名单不重新抽选。","category":"修复与优化"},{"title":"找回本地旧档","description":"读取存档中的找回入口会扫描本机当前可访问的主档、检查点及备份，校验后由你选择恢复。可恢复到空槽；六槽已满时，也可选择目标槽并二次确认覆盖，覆盖前的可用记录另留备份。来源和其他槽位保留，不会直接切换当前生涯。","category":"新增功能"},{"title":"云存档支持删除","description":"新云槽支持二次确认删除，仅清理所选云档，本地进度及其他云槽保留。删除中断可刷新后重试；本机同一生涯的自动云同步暂停，明确手动重试才会重新上传。旧云档仍保留只读。","category":"新增功能"},{"title":"云同步与长档等待优化","description":"普通上传减少重复读取，成功上传并完整校验、确认本地绑定后，再延后清理旧分片；后台清理会给前台操作让路。云恢复减少历史块重复处理，长生涯自由市场减少退役球员累积带来的结算等待，存档校验和备份保护保留。","category":"修复与优化"},{"title":"存档列表与操作布局","description":"尚未读取完成或读取失败时显示状态提示，避免误看成空槽，并完善问题诊断。旧档找回可在来源卡片内选槽；云档卡片保留原高度，恢复、删除等操作尺寸统一。","category":"修复与优化"}],"closing":"已完成的比赛和历史统计不重算。找回功能依赖本机仍完整保留且当前入口能访问的副本，无法保证恢复已清除的数据。请等待“已保存”后再退出；遇到异常可通过游戏内反馈附上设备与操作信息。"},{"date":"2026-10-23","dateLabel":"2026年10月23日","introduction":["本次优化长生涯自由市场结算，修复季后赛休息、轮换和战力计算，并完善投篮统计与加时处理。沿用现有八维能力与成长衰退规则。"],"items":[{"title":"长生涯自由市场提速","description":"优化休赛期120天自由市场结算，减少生涯累积大量退役球员后产生的等待。报价、签约、受限制自由球员的匹配决定及存档规则保持不变。","category":"修复与优化"},{"title":"季后赛休息恢复","description":"按每支球队实际休息天数恢复疲劳，修复常规赛结束及季后赛跨轮长休息仍只恢复一天的问题。","category":"修复与优化"},{"title":"自动轮换与跨年保留","description":"保留跨年时的自动或手动轮换选择。自动模式在季后赛默认集中8人轮换，提高核心球员出场时间；健康球员的合同分钟承诺仍会被考虑，手动安排保持原样。","category":"修复与优化"},{"title":"球队战力与实际出场同步","description":"球队总评按当前实际出场分钟加权，避免未出场或伤停球星抬高显示战力；零分钟球员不再影响比赛中的阵容搭配与球权冲突。部分球队显示总评会随实际轮换调整。","category":"修复与优化"},{"title":"投篮统计与加时修复","description":"优化两分、三分和罚球的统计分配，改善部分命中率偏高的情况；加时按增加的比赛时长分配出手预算，继续保持球员与球队得分、统计一致。","category":"修复与优化"},{"title":"云存档安全替换","description":"新进度上传并完整校验成功后才替换上次成功的云档，再清理上次版本的数据，避免长期保留两份。上传失败仍可恢复上次成功的云档。首次上传或旧版遗留未完成云档若没有成功版本，仍需从本地重新上传。旧云存档页签仍为旧服务档案。","category":"修复与优化"},{"title":"云存档传输优化","description":"减少上传时重复扫描槽位、重复下载整档和重复查询登录态的等待，进一步减少大档分片数量及旧档清理的重复请求。恢复优先读取已选生涯所在槽位，位置变化时重新查找；继续保留完整性校验、版本检查和本地覆盖备份。","category":"修复与优化"},{"title":"云存档恢复提速","description":"恢复云档时复用已验证的历史块原编码和同次完整校验结果，减少重复解压、校验及重新压缩；继续保留覆盖前检查、原档备份和旧档兼容。","category":"修复与优化"},{"title":"自动云同步间隔","description":"内容变化后的普通自动云同步间隔由5分钟缩短为1分钟，从上次成功上传后计时。保留上传排队、进度合并和新档校验成功后才清理旧档的保护机制。","category":"修复与优化"},{"title":"本地存档读取保护","description":"修复部分容器暂时无法访问本地数据库时误显示空存档的问题。读取异常时保留原档并提示重试，环境恢复后可重新读取。","category":"修复与优化"}],"closing":"已有八维存档可继续游玩，无需重新开档；已完成的比赛结果和历史统计保持不变。比赛仍受实际出场阵容、疲劳和状态影响，高总评不保证每场获胜。"},{"date":"2026-10-22","dateLabel":"2026年10月22日","introduction":["本次补齐真实球员头像，修正部分历史球员的身高体重；同时修复成长与比赛贡献不同步的问题，增加交易回购限制，改善云存档恢复与读档，并调整后续新秀潜力分布。已有存档可继续游玩，无需重新开档。"],"items":[{"title":"真实球员头像补齐","description":"补齐817名真实球员的头像，覆盖历史球员、2026届新秀和开档球员。旧存档可直接使用，头像仍按需加载。特别感谢虎扑JR「霸天虎ViC」的帮助与支持。","category":"新增功能"},{"title":"历史球员身高体重修正","description":"为77名此前套用位置通用身高体重的历史球员补齐逐人资料，姚明修正为226厘米、141公斤。修正用于后续首次生成的历史新秀和之后的历史球员轮回；已有存档中的球员及已发布选秀名单保留原身体数据，无需重新开档。","category":"修复与优化"},{"title":"新秀潜力分布调整","description":"后续新生成届次的潜力概率由原比例调整为：S 3% → 1%、A+ 6% → 5%、A 11% → 9%、B+ 18% → 15%、B 25% → 25%（不变）、C 25% → 28%、D 12% → 17%。沿用现有等级体系与潜力区间，每届各档人数会随机波动。历史真人、轮回与虚拟新秀共用每届潜力档位名额。","category":"修复与优化"},{"title":"旧存档与已生成新秀","description":"调整仅影响后续首次生成的选秀届次。已有球员和已生成的新秀保持原有潜力，不重新抽选；已有球探报告和选秀进度保留，旧存档无需重新开档。","category":"修复与优化"},{"title":"成长与比赛贡献同步","description":"修复部分真实及轮回球员的总评校准未计入比赛贡献的问题，成长获得的校准同步进入攻防，首届真人新秀的等价替补也适用。保留八维属性特点，已有比赛结果不重算。","category":"修复与优化"},{"title":"限制短期交易回购","description":"更新后新成交开始记录：赛季内送走的球员当季不能交易换回；休赛期送走须等接下来的赛季结束。经第三队转手也不能绕过限制，旧成交不追补。","category":"修复与优化"},{"title":"云存档中断恢复","description":"修复本机云档上传连续中断后被误判为新冲突的情况，改善重试和完成确认。自动同步继续保留，完整写入并校验后才确认同步成功，仍保护真实的版本冲突。","category":"修复与优化"},{"title":"读档与新生涯入口","description":"自动云快照读取历史资料时会在安全边界让位，减少继续生涯时的排队等待；改善部分旧容器的新生涯入口兼容，以及建队、接手球队时的进度和失败提示。","category":"修复与优化"}],"closing":"比赛校准对我方和AI统一生效，比赛仍受出场时间、阵容、疲劳和状态影响，不保证高总评必胜；首季难度与长期联盟平衡仍在持续核对。请等待“已保存”后再刷新或退出，遇到异常可通过游戏内反馈提供设备信息和操作步骤。"},{"date":"2026-10-21","dateLabel":"2026年10月21日","introduction":["本次新增球队退役球衣与雕像，加入本队球员号码和主副位置设置，并优化阶段切换备份、连续模拟保存和异常恢复。已有存档可继续游玩，无需重新开档。","历史回归球员年代跨度较大，部分资料与能力评估可能仍有偏差。欢迎通过游戏内反馈提供球员姓名和具体问题，帮助我们核对完善。不够周全的地方，先向大家说声抱歉，也请多多包涵。"],"items":[{"title":"球员卡片设置","description":"球员卡片关闭键旁新增“球员设置”，可修改本队现役球员的号码，并互换已有主副位置。号码平铺选择，点击可用号码即可保存，已占用和已退役号码不可选。球员卡片及球队赛季概览新增球衣图标和号码，主副位置合并显示。","category":"新增功能"},{"title":"退役球衣墙","description":"在“生涯 → 球队历史”中管理球队荣誉，从曾效力本队且已退役的球员中选择，可按姓名搜索，按得分、篮板、助攻、抢断、盖帽累计数据排序，不设排名门槛。支持撤销退役；号码保留期间不能再自由分配。球衣显示大写英文姓氏，长姓采用轻微拱形排版；同一球员的轮回生涯可分别纪念，也可共享同一号码。","category":"新增功能"},{"title":"球队雕像广场","description":"为已退役球衣的球员建造雕像，提供22款篮球动作造型和古铜、青铜、石雕三种材质，可自定义铭文、选择摆放地点，并支持编辑和拆除。雕像双列展示，球衣墙与雕像广场可分别收起或展开。","category":"新增功能"},{"title":"真实球衣号码补充","description":"补齐此前57名球员缺失的默认号码，并补充历史球员、真人新秀的真实号码资料。轮回球员优先使用本人真实默认号码；遇到球队号码冲突或号码已退役时，分配可用号码。0号与00号分别处理。","category":"修复与优化"},{"title":"里夫斯位置修正","description":"奥斯汀·里夫斯默认位置调整为SG/PG，符合条件的旧档默认位置同步修正，保留玩家已手动调整的位置顺序。互换主副位置不改变原首发和出场时间安排。","category":"修复与优化"},{"title":"保存与连续模拟","description":"优化阶段切换备份与连续模拟保存，复用已校验且状态一致的存档编码，修复保存后重复传递整份模拟状态的问题，减少不必要的计算与临时内存分配。保留保存失败重试、独立备份及进度冲突保护。","category":"修复与优化"},{"title":"资源加载与异常恢复","description":"优化头像、历史简介等可选资源的加载和失败重试，避免异常时反复请求；完善页面渲染异常提示、重新载入入口及反馈诊断信息，便于恢复和排查问题。","category":"修复与优化"}],"closing":"已有存档无需删除或重新开档。旧档缺失的效力时间不会凭空补齐，后续继续记录。请等待“已保存”后再刷新或关闭游戏；若仍遇到白屏或异常，可通过游戏内反馈提供操作步骤、设备信息和截图。"},{"date":"2026-10-20","dateLabel":"2026年10月20日","introduction":["本次新增本队赛季荣誉汇总，调整事件处理与保存时机，并修复现役轮回球员的成长路径；同时补充说明此前v26更新包已包含的签约与续约调整。已有存档可继续游玩，无需重新开档。","历史回归球员年代跨度较大，部分资料与能力评估可能仍有偏差。欢迎通过游戏内反馈提供球员姓名和具体问题，帮助我们核对完善。不够周全的地方，先向大家说声抱歉，也请多多包涵。"],"items":[{"title":"本队赛季荣誉","description":"赛季结果和联盟奖项页新增本队荣誉汇总，按球员列出已公布的个人奖项，以及最佳阵容、最佳防守阵容、新秀阵容和全明星入选情况，点击可查看球员详情。","category":"新增功能"},{"title":"最后一年提前续约","description":"修复新秀、短合同及部分旧合同剩余一年时无法提前续约的问题。本队正常合同剩余一年即可在允许阶段提交续约报价，报价仍需满足薪资和年限等条件，并由球员决定是否接受。","category":"修复与优化"},{"title":"本队到期球员续签","description":"合同选项页的“本队上季到期球员”支持“谈续签”，可对仍为自由球员的本队到期球员提交续签报价，并查看或撤回报价；球员接受且满足签约条件后正式签回。","category":"修复与优化"},{"title":"事件弹框与保存时机","description":"遇到待处理事件时先显示弹框，暂不在弹框出现前自动保存；选择处理成功后，先关闭已处理的弹框或更新仍需处理的内容，再开始保存，减少打开和关闭时等待保存的情况。处理结果仍在保存期间时，请等待保存完成后再退出。","category":"修复与优化"},{"title":"现役轮回球员成长","description":"修复开档现役球员及2026届真人新秀后续轮回保留潜力却未接入巅峰模板成长的问题。回归球员按保存的模板逐年成长，属性和评分校准共用年度成长上限；已有轮回存档从后续休赛期成长结算起生效，读档不直接补能力或评分，也不保证人人达到99。","category":"修复与优化"},{"title":"弹框交互与荣誉卡片","description":"减少弹框聚焦时不必要的页面滚动，调整交易来信弹框的滚动处理；完善本队荣誉卡片的悬浮与键盘聚焦显示，避免出现重复边框。","category":"修复与优化"}],"closing":"已有存档无需删除或重新开档。若显示“待保存”或“保存待重试”，请等待“已保存”后再刷新或关闭游戏。"},{"date":"2026-10-19","dateLabel":"2026年10月19日","introduction":["本次已修复部分玩家遇到的新生涯创建失败、保存失败和赛季开始报错的问题，并恢复新秀、短合同及旧合同剩余一年时的提前续约入口。请保留原设备上的存档，无需删除存档或重新开档。","本次更新幅度较大，涉及较多功能和旧档兼容，仍可能存在尚未发现的问题。如果遇到存档、比赛或其他异常，请及时通过游戏内反馈告知我们，并尽量附上报错截图、手机型号和出现问题时的操作步骤。我们会持续跟进，尽快核查和修复。感谢大家的耐心、理解与支持。","本次新增球员轮回，扩充历史真人资料与未来选秀供给，完善旧档兼容、球员生涯查看、联盟补员、合同操作和存档恢复。","历史回归球员年代跨度较大，部分资料与能力评估可能仍有偏差。欢迎通过游戏内反馈提供球员姓名和具体问题，帮助我们核对完善。不够周全的地方，先向大家说声抱歉，也请多多包涵。"],"items":[{"title":"历史真人选秀池扩充","description":"新增926名可参与未来选秀的历史球星与经典球员，连同原有134名，历史真人选秀池扩充至1060名。未来新生成的选秀按潜力档位优先匹配符合条件的真人，不足时由虚拟球员补齐；每届仍为80名候选、64个选秀名额，不重复生成同一在役真人。","category":"新增功能"},{"title":"长期生涯真人覆盖","description":"在一组完整100赛季模拟样本中，入选新秀的真人占比约97.5%，联盟正式名单中的真人占比约99.2%。正式名单按每季休赛期后的在队球员人次统计，实际存档和赛季结果可能不同。","category":"新增功能"},{"title":"现役与历史球员轮回","description":"开档现役真人与2026届真人新秀加入轮回，历史真人入选后也可在退役并等待5—10年后重新取得选秀资格。回归仍需参与同档位抽选，不保证到期立即出现；每一世的数据、合同和荣誉独立，培养成果不会累计抬高下一世起点。","category":"新增功能"},{"title":"前生今世与关注","description":"球员详情新增“前生今世”，可选择各段生涯，分别查看常规赛、季后赛累计、场均数据与荣誉。可关注已归档的退役轮回球员，能力变化按所选生涯分别比较；缺失的旧历史记录会明确标注。","category":"新增功能"},{"title":"旧存档兼容更新","description":"旧档可继续游玩，加载后完成兼容更新，接入后续真人选秀与轮回。更新期间可先浏览，完成后继续操作，失败可重试。现有球员与已生成的选秀名单保留原有资料及规则，不重新抽选、不改写已有比赛结果。","category":"修复与优化"},{"title":"球员资料与头像","description":"补充历史球员中文名、真实身份和部分人物简介，核验历史头像，改善球员卡片与球探报告的头像显示。资料与照片按需载入，未覆盖的球员继续使用缺省显示。","category":"修复与优化"},{"title":"AI补员与本队续约","description":"缺编球队优先通过正常谈判签下可用真人，减少应急虚拟球员。修正部分本队续约被报价限制误拦、自动补员底薪未按球龄计算，以及普通续约成功后仍保留旧底薪标记的问题。","category":"修复与优化"},{"title":"提前续约与合同管理","description":"本队正常合同剩余一年即可在开放阶段提前续约，包括新秀和原约1—2年的球员，不再受新秀限定窗口、原约年限或签约周年拦截。季后赛可在“管理 → 合同薪资”报价；休赛期合同管理集中在首个“合同选项”页面，不在后续每页新增顶部入口。季后赛报价随实际跨日结算，合同选项页可单独结算续约报价，出现劝回待办时暂停并保存。合同页说明不能续约的原因，裁员入口与业务允许阶段统一，休赛期也可进入合同薪资页操作。","category":"修复与优化"},{"title":"自由市场保存重试","description":"自由市场计算完成但保存失败时，在当前页面保留本次结果供重试；重试只保存已完成的报价与签约结果，避免重新计算。进度冲突时明确提示，防止旧结果覆盖新进度。","category":"修复与优化"},{"title":"设备兼容与继续生涯","description":"修复部分旧版手机WebView因缺少系统能力导致的生涯创建或读取报错；改善后台同步调度，减少继续生涯时本地读档的等待。","category":"修复与优化"}],"closing":"已有存档无需删除或重新开档。真人回归受选秀档位与身份占用限制，不保证每届全部为真人；旧档缺失的历史资料不会凭空补齐。"},{"date":"2026-10-16","dateLabel":"2026年10月16日","introduction":["新增球员关注、生涯累计，优化选秀、合同、交易与存档性能。本次云存档切换至新服务，本地进度继续保留，旧云档可按需迁移。"],"items":[{"title":"新云存档与旧档迁移","description":"新进度同步到新云存档服务，旧云档保留只读，不会自动批量搬迁或删除。请在“云存档”中切换到“旧云存档”，选择生涯后“迁移到新云存档”；已有完整新云档的生涯会标记“已在新云存档”。完整写入并读回校验后才确认成功，失败保留旧档与本地进度。旧云档不会继续记录新版进度。","category":"新增功能"},{"title":"十个云端生涯与容量显示","description":"新云存档提供10个生涯槽位，本地仍为6个。打开云存档可查看每份大小、同步容量预算及占用百分比；100 MiB 是游戏设置的预算。槽位或预算不足时由你选择替换，不会静默删除。超过10个的旧云档仍可读取并按需选择迁移。","category":"新增功能"},{"title":"持续关注球员","description":"可关注已进入联盟的球员，转队后继续追踪，并查看关注后的能力变化。","category":"新增功能"},{"title":"队史抢断与盖帽榜","description":"得分、篮板、助攻、抢断、盖帽各列前10，默认展开得分榜。旧档抢断、盖帽从更新后下一场本队常规赛起累计，不回填历史。","category":"新增功能"},{"title":"球员生涯累计","description":"新增生涯累计，可查看总得分、篮板、助攻等数据，区分常规赛与季后赛。","category":"新增功能"},{"title":"具体伤病","description":"新伤病显示具体名称；旧伤病保留原恢复进度。","category":"新增功能"},{"title":"选秀排序切换","description":"默认按本队球探排序，可切换媒体排名。","category":"新增功能"},{"title":"递减合同与保障比例","description":"支持年薪递减：外队±5%、本队续约按原资格±8%；保障比例改为每5%一档。","category":"修复与优化"},{"title":"跨球队寻找交易目标","description":"可跨球队按主、副位置和姓名找人，选人后继续组合该队资产。","category":"修复与优化"},{"title":"媒体选秀预测","description":"缩小媒体排名偏差，本队球探仍随考察深入提高精度；已公布榜单保留。","category":"修复与优化"},{"title":"新秀参考模板","description":"按位置和已知特点匹配模板，取消固定套用；精简报告布局。","category":"修复与优化"},{"title":"加时赛分节比分","description":"修复加时及多加时分节比分错误，旧比赛结果不变。","category":"修复与优化"},{"title":"云存档同步优化","description":"自动云同步仅在内容变化、距上次成功上传至少5分钟时触发；手动保存和关键进度可提前同步，本地保存仍及时进行。","category":"修复与优化"},{"title":"云同步异常处理","description":"合并等待中的重复同步请求，按最新本地进度依次上传；失败暂停自动重试，本地进度继续保存。同一生涯只保留一份云档，覆盖上传期间暂不可恢复；中断后显示“上传未完成”，可在原设备选择“从本地重新上传”，完整校验成功后恢复读取。请勿清除本地存档或同时在多台设备上传；遇到版本冲突先确认要保留的进度。","category":"修复与优化"},{"title":"长生涯历史存档精简","description":"精简游戏内没有查看入口的历年比赛冗余数据，保留可查看的关键比赛、球员历年数据和队史纪录，减少长生涯存档体积。旧本地存档可继续读取，不改变已有比赛结果与生涯进度。","category":"修复与优化"},{"title":"存档性能优化","description":"优化存档压缩校验、编码和哈希计算，减少重复计算与临时内存开销，旧存档继续兼容。","category":"修复与优化"},{"title":"载入与异常反馈","description":"增加启动载入与失败重试提示，完善队徽回退、存档耗时与问题诊断。","category":"修复与优化"}],"closing":"本地旧档无需手动转换；旧云档请按需迁移，恢复到本地前会先备份原进度。请保留原设备本地存档。关注从添加时记录，媒体榜新规则用于后续新届次，既有合同不变。"},{"date":"2026-10-15","dateLabel":"2026年10月15日","introduction":["本次新增接手球队模式与六个生涯存档，改善读档、云同步和球队经营操作体验。","本次还优化了自由市场计算、交易来信弹框和轮换球员卡片。"],"items":[{"title":"接手球队模式","description":"可选择原有30支球队之一，继承阵容、合同和选秀权，提交8人保护名单应对联盟扩军。西雅图与拉斯维加斯各选14人，本队最多损失1人；之后接入共用的新秀选秀、自由市场与赛季流程。","category":"新增功能"},{"title":"六个生涯存档","description":"存档槽位由3个增加到6个，两种模式共用，原有存档继续保留。独立标签区分扩军建队和接手球队；尚未选队的接手生涯显示待选择球队。","category":"新增功能"},{"title":"读档与云同步","description":"显示读取步骤与等待时间，完善超时、取消和旧档保护。减少首页继续读取与云同步的重复历史扫描；自动同步优先避让自由市场操作及年度阶段切换，补充反馈诊断。","category":"修复与优化"},{"title":"报价与续约","description":"未开放阶段明确提示暂不能报价；未接受的自由球员和提前续约报价可跨阶段撤回，季后赛也可操作并释放预留。正式合同及RFA记录保留原保护。","category":"修复与优化"},{"title":"自由市场计算优化","description":"减少AI报价计算中的重复扫描和薪资、角色统计，降低报价记录较多时的计算开销，继续使用原有报价与签约规则。","category":"修复与优化"},{"title":"交易来信弹框","description":"增加轻量入场过渡，减少重复聚焦和返回时的页面跳动；减少动态效果时关闭动画，仍在保存成功后开放交易操作。","category":"修复与优化"},{"title":"轮换球员卡片","description":"文字和卡片空白区域也更容易打开球员详情，球员选择和轮换编辑控件继续独立操作。","category":"修复与优化"},{"title":"首页退出提示","description":"首页网页返回时提供继续游戏、退出游戏，避免误操作离开游戏。原生退出需App支持。","category":"新增功能"}]},{"date":"2026-10-14","dateLabel":"2026年10月14日","introduction":["本次新增选秀球探，完善选秀、日历与球员报告体验。"],"items":[{"title":"选秀球探","description":"开季可查看80名新秀，关注目标、安排考察并整理选秀板。初步考察、深入考察、联合试训每阶段需14天、消耗1次考察。","category":"新增功能"},{"title":"球探与自动考察","description":"每届默认1名球探、45次考察，可观看视频增聘至4名。支持统一设置自动考察目标。","category":"新增功能"},{"title":"专家评估预约","description":"常规赛观看视频预约，联合试训完成后自动公开准确能力与潜力；专家评估本身不消耗考察次数和天数。","category":"新增功能"},{"title":"选秀结果","description":"结果公开能力与潜力，前三顺位用金银铜标识，点击球员可查看详情。","category":"修复与优化"},{"title":"日历与通知","description":"季后赛和选秀准备可快进天数，日历同步比分、考察报告及模拟动画。通知按伤病、球探等分类，顶部阶段提示更清晰。","category":"修复与优化"},{"title":"休赛期交易","description":"修复合同到期后球队不足5人，询价和交易被错误拦截的问题；补齐名单后再建立轮换。","category":"修复与优化"},{"title":"存档读取恢复","description":"改善存储短暂中断后的读取恢复；仍无法读取时保留原存档，并提供明确提示和重试入口。","category":"修复与优化"}]},{"date":"2026-10-13","dateLabel":"2026年10月13日","introduction":["球探功能即将上线，敬请期待！","对于此前因本地存档丢失而失去生涯进度的玩家，我们真诚地向大家说一声：对不起。一支球队、一个赛季背后，都是大家投入的时间和心血。让这些努力因为存档丢失而落空，我们非常抱歉。这次新增云存档，希望能为大家的生涯进度多一份保障。感谢大家愿意反馈问题，也感谢大家的耐心与信任。"],"items":[{"title":"历史传奇新秀能力","description":"恢复部分传奇新秀至少80的初始能力，通过真实属性提升，并保留成长空间。穆托姆博等防守、篮板或其他专长型球员保持各自的自然起点，其他历史球员继续原有分层。","category":"修复与优化"},{"title":"历史球员实战表现","description":"修复历史球员成长后显示能力提高、比赛攻防却未体现这部分提升的问题。已获得的评分提升会在后续比赛中生效；旧存档可直接继续，已有比赛结果保持。","category":"修复与优化"},{"title":"云同步与存读档界面","description":"修复云身份识别，云同步异常可查看原因并重试。存读档采用保存、读取、云存档三个页签，固定同步状态与操作按钮的位置；云列表单独滚动，保留覆盖确认、本地备份与撤销。","category":"修复与优化"},{"title":"云存档","description":"本地保存后自动同步到当前账号，并显示同步状态。云端生涯数量不限，可选择云档恢复到任意本地槽位，覆盖前保留本地备份；历史比赛、球员历季数据和退役资料也会一起保存。","category":"新增功能"},{"title":"自由市场续约修复","description":"有待处理的续约决定时，请先完成决定；处理后可继续每日结算和自由市场模拟。","category":"修复与优化"},{"title":"首发与轮换修复","description":"修复伤停时首发替补调整和分钟保存不一致的问题，区分保存方案与当前出战预览；清理失效、重复及与首发冲突的替补顺序，修复正常互换后无法保存的问题。","category":"修复与优化"},{"title":"选秀权交易反馈","description":"修复询价被拒绝时提示藏在屏幕外、看似没有响应的问题。经理回复会自动展示，游戏进度变化时也会明确提示重新询价。","category":"修复与优化"}]},{"date":"2026-10-12","dateLabel":"2026年10月12日","introduction":["本次更新简化选秀球探流程，调整长期生涯的薪资增长，并提高历史球员进入选秀的机会。"],"items":[{"title":"选秀球探流程简化","description":"每届常规考察增加到36次，可选择免费考察到第1、2或3轮，达到目标后停止；第四轮视频核验可获得100%精准能力和潜力。选秀前每轮需要14个游戏日，未进季后赛、已淘汰和选秀前休赛时可单独推进考察；选秀大会期间视频立即出下一轮结果。媒体潜力先显示三个相邻档位；第一轮收窄能力，第二轮收窄潜力，第三轮继续收窄能力，88%仍为估计，第四轮才公开准确值。视频支援每次增加3次考察机会，不限领取，潜力范围统一用‘至’区分。","category":"新增功能"},{"title":"工资帽增长调整","description":"新生涯的工资帽先每年上涨7%，持续五年；接下来五年每年上涨5%，再五年每年上涨3%，完成十五次年度上涨后固定。奢侈税线及两道土豪线同步调整。","category":"修复与优化"},{"title":"旧存档继续可用","description":"旧生涯未满十五年时，仍按每年7%上涨，到十五年后停涨；已超过十五年的旧生涯，保持当前赛季的工资帽和奢侈税线，此后不再上涨。可直接读取旧存档继续游戏，无需重开生涯。","category":"修复与优化"},{"title":"合同与薪资衔接","description":"底薪、新秀薪资和顶薪标准随当前生涯的工资帽计算。已签合同继续执行原有逐年薪资，工资帽停涨不会取消合同约定的涨幅；旧存档已提交的续约报价保留原金额。","category":"修复与优化"},{"title":"历史球员新秀概率提高","description":"历史新秀分两组独立抽取：S级每届0名10%、1名60%、2名25%、3名5%；A+、A、B+合计每届1名50%、2名35%、3名15%，合计至少一名。两组总计最多六名，选秀候选人仍为80名。分组按真实潜力计算，媒体预测和未完成的球探评估可能存在误差，并非某位球星的单独出现概率。已生成的新秀名单保持原样，新旧存档后续生成的选秀班使用新规则。","category":"修复与优化"}]},{"date":"2026-10-11","dateLabel":"2026年10月11日","introduction":["感谢大家的体验与反馈，本次更新主要包括："],"items":[{"title":"新增13名退役球员","description":"退役球员池增至134人，新增肖恩·巴蒂尔、杰森·理查德森、理查德·汉密尔顿、拉沙德·刘易斯、肖恩·马里昂、拉马尔·奥多姆、鲍里斯·迪奥、迈克·米勒、凯尔·科沃尔、路易斯·斯科拉、JJ·雷迪克、钱宁·弗莱和犹多尼斯·哈斯勒姆。新档及旧档的后续赛季选秀都有机会抽到，已有球员与已生成的当届名单保持原样。","category":"新增功能"},{"title":"联盟伤病情况","description":"联盟页面新增伤病情况，可查看各队当前伤员、伤停级别和预计剩余天数，支持按球队筛选、快捷查看本队，点击球员可打开详情。","category":"新增功能"},{"title":"普通伤病专家会诊","description":"伤病事件中的专家会诊不再只限赛季报销，符合条件的本队普通伤停也可使用。完整观看激励视频后，剩余伤停时间缩短60%；同一事件仅可使用一次，球员仍需休养。","category":"新增功能"},{"title":"存档附件反馈","description":"读取存档菜单和加载界面新增存档问题反馈，可说明问题并手动选择存档或诊断文件作为附件提交。提供导出JSON诊断包、保存到手机文件及选择上传的操作指引。","category":"新增功能"},{"title":"生涯总览与排名","description":"生涯总览新增当前生涯冠军率，排行榜入口同时显示账号的冠军率、总冠军数和王朝积分排名。榜单继续采用账号最高王朝积分的生涯成绩，冠军率排名仍要求完成至少10个赛季。","category":"新增功能"},{"title":"球队选项操作","description":"球队选项阶段可点击球员查看完整资料；放弃球队选项时增加确认提示，减少误操作。","category":"新增功能"},{"title":"AI 主动交易","description":"AI 球队会主动发来交易报价，每 21 个游戏日最多一份，有效期 7 天。收到报价时暂停连续模拟，可查看、拒绝、忽略本次或忽略本赛季。","category":"新增功能"},{"title":"底薪合同","description":"支持向自由球员报价一年或两年底薪合同，工资按球龄和赛季标准自动计算，可超工资帽签约。","category":"新增功能"},{"title":"历史巨星新秀出现概率","description":"降低历史巨星与退役球员进入新秀名单的频率。每届按0名40%、1名35%、2名20%、3名5%的概率抽取历史球员数量，三名同时出现的概率由45%降至5%。不同档次的历史球员都有机会出现；旧档已生成的新秀名单保持原样，后续赛季使用新规则。","category":"修复与优化"},{"title":"球员专项成长","description":"成长更注重球员的位置、特长与潜力，历史球星保留更鲜明的强弱项，接近各项成长上限时放缓。取消按固定年龄强制补齐能力；旧档已有属性不会因本次上限调整被回溯降低，后续按新规则成长及正常衰退。","category":"修复与优化"},{"title":"旧存档加载","description":"减少兼容补齐、历史数据检查和进入游戏时的重复处理，优化长期生涯的读档响应；读档时不再执行可选的虚拟球员清理，继续保留存档损坏检查和备份恢复。","category":"修复与优化"},{"title":"康复与模拟提示","description":"修正专家会诊后的伤情与康复提示；点击模拟暂停后显示“暂停中”，等待当前处理完成，减少重复点击。","category":"修复与优化"},{"title":"交易报价界面","description":"优化报价布局与颜色，补充球员头像、位置、年龄、能力和潜力，支持点击查看球员资料。拒绝的报价立即隐藏，忽略的报价到期后隐藏。","category":"修复与优化"},{"title":"合同薪资","description":"修正两年底薪的第二年工资计算，以及部分普通报价低于对应底薪的问题，优化金额和合同说明展示。","category":"修复与优化"},{"title":"模拟与存档性能","description":"减少连续模拟、赛季切换和自动保存中的重复处理，改善长期生涯的运行响应。","category":"修复与优化"},{"title":"异常反馈","description":"自由市场结算或保存失败时，可返回重试、反馈问题或导出诊断文件。","category":"修复与优化"}],"closing":"感谢大家持续反馈。如仍遇到问题，请附上手机型号、系统版本及出现问题的具体操作；读档异常可通过存档问题反馈附上诊断文件，方便继续排查。"},{"date":"2026-10-10","dateLabel":"2026年10月10日","introduction":["感谢大家的体验与反馈，本次更新主要包括："],"items":[{"title":"冠军率与冠军数榜单","description":"排行榜新增冠军率、冠军数，可切换查看排名。榜单采用账号最高得分生涯的成绩，冠军率按夺冠次数／已完成赛季计算，完成至少10个赛季可参与冠军率排名。","category":"新增功能"},{"title":"球员选秀信息","description":"球员卡片补充选秀年份与总顺位，可查看已收录的真实球员选秀资料，并兼容旧存档显示。","category":"新增功能"},{"title":"生涯荣誉详情","description":"点击球员的生涯荣誉，可按荣誉类型查看有记录的获奖赛季。","category":"新增功能"},{"title":"季后赛近期赛果","description":"赛季结算后可查看本队最近三场季后赛，点击比赛打开技术统计，方便回顾最后几场表现。","category":"新增功能"},{"title":"休赛期定位调整","description":"自由市场的当前阵容中可直接调整球员定位、协商已有签约承诺，便于签约前安排角色名额。","category":"新增功能"},{"title":"全明星评选","description":"全明星改为每年2月15日按当时的赛季表现评选，本队球员入选时收到通知；季末保留已公布名单，不重复增加荣誉。","category":"修复与优化"},{"title":"提前续约与鸟权","description":"修正常规赛结束后的提前续约入口，避免提交无法继续结算的报价，最后比赛日前的有效报价仍照常结算；修正新开局与读档后的鸟权累计一致性。","category":"修复与优化"},{"title":"开季名单锁定","description":"修复部分球队伤员过多时无法锁定名单并进入常规赛的问题；伤员仍按原规则休养，比赛日继续检查可用阵容。","category":"修复与优化"},{"title":"交易筹码弹层","description":"优化双方添加筹码弹层的显示与滚动兼容性。","category":"修复与优化"},{"title":"长期生涯与存读档","description":"减少年度切换时的重复处理；后台编解码无响应时，避免在同一次存读档操作中反复等待，继续保留球员资料与赛季历史。","category":"修复与优化"},{"title":"自由市场响应","description":"减少进入市场、搜索和查看报价时的重复计算，改善大名单与长期生涯的操作响应。","category":"修复与优化"},{"title":"问题反馈","description":"自动补充当前赛季、阶段、页面和保存状态，慢操作报告保留关键耗时步骤，方便进一步排查。","category":"修复与优化"}],"closing":"感谢大家持续反馈。如仍遇到问题，请附上手机型号、系统版本及出现问题的具体操作，方便继续排查。"},{"date":"2026-10-09","dateLabel":"2026年10月9日","introduction":["感谢大家的体验与反馈，本次更新主要包括："],"items":[{"title":"球员定位与签约承诺","description":"可统一设置球队核心、重要主力、第六人等定位；签约与续约时明确待遇承诺，可查看履约进度并协商调整。球员拒绝时可观看激励视频说服，仍需满足定位容量。","category":"新增功能"},{"title":"三个进攻点","description":"每赛季默认两个进攻点，观看激励视频后解锁本赛季第三进攻点，新赛季重新锁定；伤停时临时顺延，复出后恢复原设置。","category":"新增功能"},{"title":"自由市场联盟动态","description":"可查看上一结算日的全部签约动态，并按日期浏览完整历史，支持搜索球队或球员。","category":"新增功能"},{"title":"轮换与季前准备","description":"优化自动轮换、定位与训练控件；仅核心、重要主力、第六人的签约承诺提供时间保障，普通定位不做分钟考核，保留手动调整。","category":"修复与优化"},{"title":"球权与三分表现","description":"调整主攻点与轮换球员的出手机会，减少球权过度集中；三分命中更体现投射能力，改善少量出手的统计偏差。","category":"修复与优化"},{"title":"球员成长与巅峰","description":"完善潜力约束和26～29岁成长窗口，让高潜力球员更充分兑现能力；加强高龄球员的身体衰退。","category":"修复与优化"},{"title":"退役与合同履约","description":"优化老将退役风险；尚有后续年份的标准合同先履行完，合同末年再结合年龄、能力和身体状态评估退役。","category":"修复与优化"},{"title":"长期生涯与存档","description":"减少年度切换的重复计算与数据传输，清理符合条件的无记录虚拟球员；退役球员的生涯、荣誉和比赛历史继续保留，完整资料按需读取。","category":"修复与优化"}]},{"date":"2026-10-08","dateLabel":"2026年10月8日","introduction":["感谢大家的体验与反馈，本次更新主要包括："],"items":[{"title":"球员季后赛生涯数据","description":"球员卡片的生涯数据新增常规赛／季后赛切换，可查看历年季后赛表现；旧档缺失的数据会明确提示。","category":"新增功能"},{"title":"伤病专家会诊","description":"本队球员赛季报销时，可在伤病事件中选择观看激励广告，完成后将剩余伤停时间缩短60%；球员仍需休养，未完成广告则不改变伤情。","category":"新增功能"},{"title":"历史球星扩充","description":"新增31名退役明星，包括安芬尼·哈达威、斯蒂芬·马布里、肯巴·沃克、约翰·沃尔等；纳入后续选秀，使用普通明星的培养规则。","category":"新增功能"},{"title":"季后赛模拟与过渡","description":"模拟整轮时保留对阵卡片，比赛结果逐场展示，比分和系列赛战绩同步更新；晋级时弹框提示下一轮对阵，总决赛胜负及总冠军诞生均有弹框提醒，冠军弹框显示总决赛MVP。","category":"修复与优化"},{"title":"模拟与续约性能","description":"减少交易截止日前快进、提交续约和进入下一赛季时的重复计算与数据复制，优化合同记录显示，减少等待和卡顿。","category":"修复与优化"},{"title":"新秀供给平衡","description":"调整未来普通新秀的潜力与即战能力分布，增加选秀大小年的变化；每届历史球星由固定3人调整为随机1至3人，已有球员和已生成的选秀班保持。","category":"修复与优化"},{"title":"自由市场薪资与报价","description":"明确区分薪资占位和建议首年报价，统一列表与报价编辑器的参考口径；优化鸟权薪资占位计算，保留签约权列表可查看已提交报价并直接撤回。","category":"修复与优化"}]},{"date":"2026-10-07","dateLabel":"2026年10月7日","introduction":["感谢大家的体验与反馈，本次更新主要包括："],"items":[{"title":"交易谈判","description":"交易详情可增减双方球员和选秀权，向对方经理询价；经理会同意、还价或拒绝。","category":"新增功能"},{"title":"比赛详情查看球员","description":"点击比赛详情中的球员姓名，即可查看球员信息。","category":"新增功能"},{"title":"模拟到常规赛结束","description":"新增一键模拟到常规赛结束，与连续模拟5场并排显示；模拟中可随时暂停，季后赛由玩家手动继续。","category":"新增功能"},{"title":"事件处理后续跑","description":"选择自动处理方案后继续原模拟目标，手动调整则暂停；交易截止日前提醒继续模拟或暂停去交易。","category":"新增功能"},{"title":"本赛季伤病免提醒","description":"可选择按原方案临时补位，并在本赛季不再提醒；保留原轮换，名单不足时仍会提示补人。","category":"新增功能"},{"title":"交易优化","description":"目标搜索仅展示一个报价，优化还价合理性、筹码筛选、按钮布局及操作响应。","category":"修复与优化"},{"title":"核心球员保护","description":"普通核心保护上限调整为2人，指定非卖品继续保留保护。","category":"修复与优化"},{"title":"选秀权估值","description":"修复远期首轮估值低于次轮的问题。","category":"修复与优化"},{"title":"复盘鼓舞","description":"随机鼓舞两人和鼓舞全队均提升10点士气。","category":"修复与优化"},{"title":"球员位置","description":"修正杰伦·威廉姆斯为得分后卫/小前锋，兼容旧存档。","category":"修复与优化"},{"title":"模拟存档优化","description":"连续模拟5场结束保存；长模拟每5场比赛或10个游戏日保存，先到即保存，事件、暂停及结束立即保存。","category":"修复与优化"}]},{"date":"2026-10-06","dateLabel":"2026年10月6日","introduction":["感谢大家的体验与反馈。本次更新在10月4日版本的基础上，新增球员详情与经营功能，并集中优化模拟、交易和存档体验："],"items":[{"title":"球员卡片","description":"新增球员信息、生涯数据、生涯荣誉、合同详情四个标签，可查看潜力评级、历年常规赛表现、荣誉次数，以及逐年薪资、保障和合同选项。"},{"title":"生涯数据","description":"新赛季结束后保留球员年度统计，常规赛数据按年份倒序展示；旧档仅展示可确认的数据，部分比赛样本会明确标注。"},{"title":"自由市场模拟","description":"新增模拟至市场结束和实时进度，已提交报价继续结算；遇到本队 RFA 匹配决定时暂停，处理后继续。"},{"title":"RFA 签约","description":"常规赛仍可向未签约的受限自由球员报价，并保留原队匹配权；优化市场末期报价与匹配结算。"},{"title":"AI 续约与建队","description":"AI 可在常规赛提前续约，优化核心球员预算预留和签约优先级，并根据年龄与球队需要调整合同年限和阵容补强。"},{"title":"市场薪资平衡","description":"优化长期生涯中的工资预期和报价年限，减少高能力球员长期无人有效报价；已有合同金额保留。"},{"title":"新秀与历史球星","description":"新增新秀选中后的签约或放弃决定；延长历史球星新秀的成长周期，减少过早达到巅峰的情况。"},{"title":"交易入口与报价","description":"休赛期自由市场可切换到交易中心，优化多人交易的合法报价搜索；全部报价失效后可重新询价。"},{"title":"交易与续约记录","description":"当前赛季可查看交易和续约记录，包含休赛期交易及已达成、待生效的续约，便于追踪阵容变化。"},{"title":"伤病临时补位","description":"缺少同位置接班人时，可通过兼容位置和分钟分摊完成临时补位；保留原轮换方案，复出后恢复。"},{"title":"抢断与盖帽","description":"结合 NBA 参考产出、能力和上场时间调整防守统计，改善大量球员场均固定在1.0的现象；旧赛季已有累计保留。"},{"title":"模拟与内存优化","description":"优化一周模拟、季后赛和后台计算不可用时的处理，减少长时间无响应；历史比赛与历史球星头像按需查看和加载。"},{"title":"存档读取兼容","description":"改进压缩存档读取兼容和完整性校验，暂时无法读取时保留原档；旧存档可继续使用。"},{"title":"历史公告","description":"更新公告中可展开查看历史版本内容，最新公告完整展示。"}],"closing":"感谢大家持续反馈。如仍遇到模拟、交易或存档问题，请附上手机型号、系统版本及出现问题的具体操作，方便继续排查。"},{"date":"2026-10-04","dateLabel":"2026年10月4日","introduction":["感谢大家的体验与反馈，本次更新主要包括："],"items":[{"title":"运行性能","description":"优化赛季模拟、年度切换、交易询价和存读档，减少等待与内存占用。"},{"title":"选秀期间交易","description":"选秀大会可交易球员和未使用的选秀权，入口移至候选新秀上方；成交后同步签位归属。"},{"title":"交易筹码选择","description":"目标资产先选球队，再选球员或选秀权；我方筹码改为左右标签切换，首轮与次轮签使用不同标识和颜色。"},{"title":"轮换与伤病","description":"手动轮换保留首发与分钟设置，伤停临时补位、复出后恢复；新赛季默认手动，一键匹配保留当前模式，暂停上场时间与球队角色诉求事件。"},{"title":"存档保护","description":"加强存档校验、备份恢复和异常重试，修复部分保存失败误报；暂时无法读取时保留原档并提示重试。"},{"title":"自动保存提示","description":"顶部显示保存中、已保存或保存失败，云同步异常单独提示；保存失败可重试。"}]},{"date":"2026-10-03","dateLabel":"2026年10月3日","introduction":["本次更新主要优化轮换操作和比赛后的球队管理："],"items":[{"title":"轮换模式","description":"轮换页可切换手动与自动模式，并保留一键自动匹配；手动模式保留玩家设置的首发和分钟。"},{"title":"伤病接班","description":"首发与替补伤停时按主副位置安排临时接班，复出后恢复原分配；无法补位时提示调整轮换。"},{"title":"比赛复盘","description":"近五场复盘可直接鼓舞球员；奖励已确认但保存失败时，可直接重试保存。"},{"title":"角色诉求","description":"修复部分老将已经首发或上场时间充足，仍触发角色调整诉求的问题。"}]},{"date":"2026-10-02","dateLabel":"2026年10月2日","introduction":["感谢大家自上线以来的体验与反馈，也很抱歉目前游戏中还存在一些影响体验的问题。大家提出的每一条建议我都会认真查看，并积极修复和优化。我会继续努力完善游戏，希望给大家带来更好的游戏体验。","针对近期玩家反馈，我对游戏体验进行了集中优化："],"items":[{"title":"伤病与轮换","description":"伤病后自动调整轮换，仅在可用人数不足时触发紧急补员，减少比赛中断。"},{"title":"补员机制","description":"优化紧急补员与开幕补员逻辑，避免补入过强球员影响阵容平衡。"},{"title":"体能系统","description":"提高休息日体能恢复效果，减少频繁调整轮换的情况。"},{"title":"合同与续约","description":"新增球员提前续约功能，可在合同到期前向本队球员提交续约报价。"},{"title":"选秀与交易","description":"修复选秀前交易中心部分情况下出现黑屏的问题。"},{"title":"生涯与通知","description":"减少里程碑及历史成就的重复通知，修复老存档相关问题。"}],"closing":"感谢大家的反馈，我会继续根据实际体验持续调整和优化。"}];globalThis.__NBA_STARTUP_DATA_BUILDS__=globalThis.__NBA_STARTUP_DATA_BUILDS__||{};globalThis.__NBA_STARTUP_DATA_BUILDS__.announcements="source-5c54a129d626ddfa";